/* A22 · frozen 80-word manifest; four exact 20-word checkpoints. */
(function(g){
  'use strict';
  const D=g.RA.D;
  const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline — '+w+'; https://www.etymonline.com/word/'+w.toLowerCase()});
  const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
  const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
  const Q=(w,n,s,prompt,options,answer,explain,errorType='meaning')=>({id:w+'.q'+n,senseId:w+'.s'+s,errorType,type:'语境辨义',prompt,options,answer,explain});

  D('deceit',{etymology:E('deceit entered Middle English through Anglo-French deceite, from the verb deceive; the family ultimately goes back to Latin decipere, “to ensnare or cheat.”','deceit'),contexts:[C('deceit.s1','新闻调查','The audit uncovered deliberate deceit: invoices had been altered so that the charity appeared to have paid suppliers twice.','审计揭露了蓄意欺骗：发票被篡改，使慈善机构看起来向供应商付了两次款。','The audit uncovered deliberate deceit / invoices had been altered / so that the charity appeared to have paid suppliers twice.','冒号后的事实解释 deceit 的具体表现。','伪造发票以误导审计，体现欺骗行为义。')],mistakes:[M('The report praised the manager’s deceit because she disclosed every cost accurately and hid nothing.','The report praised the manager’s honesty because she disclosed every cost accurately and hid nothing.','如实公开且没有隐瞒体现诚实，而不是 deceit。')],quiz:[Q('deceit',1,1,'What did the audit uncover when invoices were intentionally falsified?',['deceit','generosity','a bookkeeping holiday'],'deceit','Intentionally misleading people is deceit.'),Q('deceit',2,2,'Which quality is the opposite of deceit?',['honesty','concealment','fraud'],'honesty','Deceit is dishonesty; honesty is its opposite.'),Q('deceit',3,1,'A scheme designed to make buyers believe a false claim is an act of?',['deceit','patience','decoration'],'deceit','A deliberately misleading scheme is deceit.'),Q('deceit',4,2,'In “the deceit of the witness,” deceit most nearly means?',['dishonesty','careful measurement','public ceremony'],'dishonesty','The noun can name the quality of being dishonest.') ]});
  D('deceitful',{etymology:E('deceitful is formed from deceit plus the adjective suffix -ful, “characterized by” or “full of.”','deceitful'),contexts:[C('deceitful.s1','消费提醒','The deceitful seller described a used phone as new and concealed the cracked screen beneath a case.','这个不诚实的卖家把二手手机说成新品，还用手机壳遮住裂屏。','The deceitful seller described a used phone as new / and concealed the cracked screen / beneath a case.','deceitful 修饰 seller；两个并列动作展示其行为。','卖家故意隐瞒真相以误导顾客，符合 s1。')],mistakes:[M('The deceitful notice gave the full price, listed every fee, and clearly disclosed the contract terms.','The transparent notice gave the full price, listed every fee, and clearly disclosed the contract terms.','完整披露价格和条款并不欺诈；transparent 更符合此语境。')],quiz:[Q('deceitful',1,1,'A seller hides a defect and lies about a phone’s condition. The seller is?',['deceitful','punctual','decorative'],'deceitful','The seller deliberately hides the truth.'),Q('deceitful',2,2,'A deceitful smile is one intended to?',['make someone believe something false','show an accurate map','measure sound intensity'],'make someone believe something false','The word can describe a misleading expression or appearance.'),Q('deceitful',3,1,'Which action is most clearly deceitful?',['claiming a damaged item is flawless','listing a product’s defects','refunding a mistaken charge'],'claiming a damaged item is flawless','The false claim intentionally misleads the buyer.'),Q('deceitful',4,2,'Choose the closest meaning of “deceitful advertising.”',['advertising that misleads people','advertising that gives verifiable facts','advertising placed outdoors'],'advertising that misleads people','Deceitful describes something meant to trick or mislead.') ]});
  D('deceptive',{etymology:E('deceptive comes through French from Latin deceptivus, from decipere “to deceive”; it describes either a misleading appearance or deliberate dishonesty.','deceptive'),contexts:[C('deceptive.s1','地形观察','From the road the ridge looked close, but the deceptive perspective hid another two hours of climbing.','从公路上看山脊似乎很近，但这种造成错觉的视角掩盖了还要爬两个小时的事实。','From the road the ridge looked close / but the deceptive perspective / hid another two hours of climbing.','deceptive 修饰 perspective；but 引出表象和实际的反差。','视角使距离看起来比实际短，体现“造成错觉”义。'),C('deceptive.s2','商业诚信','The company used deceptive pricing by advertising a low monthly fee while hiding a large mandatory charge in the contract.','该公司采用欺诈性定价：广告宣传低月费，却把一笔大额强制收费藏在合同里。','The company used deceptive pricing / by advertising a low monthly fee / while hiding a large mandatory charge in the contract.','by + 动名词解释欺骗手段；while 对比宣传和隐瞒。','隐去强制收费以误导消费者，符合欺诈义。')],mistakes:[M('The label was deceptive because it accurately listed the ingredients and clearly stated the serving size.','The label was informative because it accurately listed the ingredients and clearly stated the serving size.','信息准确且清楚的标签没有造成错误印象，不应称为 deceptive。')],quiz:[Q('deceptive',1,1,'A distant hill seems low only because of the viewing angle. Its appearance is?',['deceptive','nutritious','deciduous'],'deceptive','The appearance gives a false impression of the hill’s height.'),Q('deceptive',2,2,'A hidden mandatory fee makes an advertised offer?',['deceptive','transparent','seasonal'],'deceptive','The omitted charge misleads customers.'),Q('deceptive',3,1,'Which clue indicates a deceptive estimate?',['it looks precise but leaves out major costs','it includes all assumptions and costs','it matches the final bill exactly'],'it looks precise but leaves out major costs','Omitted costs make the estimate misleading.'),Q('deceptive',4,2,'The adjective deceptive can describe?',['a dishonest tactic or a misleading appearance','a tree that sheds leaves','a unit used to measure sound'],'a dishonest tactic or a misleading appearance','Both senses involve an impression that does not match reality.') ]});
  D('decibel',{etymology:E('decibel was formed from deci-, “one tenth,” and bel, a unit named for Alexander Graham Bell; a decibel is one tenth of a bel on a logarithmic scale.','decibel'),contexts:[C('decibel.s1','声音测量','The technician measured the alarm at 82 decibels and fitted a quieter signal before the night shift began.','技术员测得警报声为82分贝，并在夜班开始前换装了更安静的信号器。','The technician measured the alarm at 82 decibels / and fitted a quieter signal / before the night shift began.','measure + 声音 + at + 数值；decibel 是响度常用单位。','数字表示仪器测得的声级，符合分贝义。')],mistakes:[M('The sound meter reported the siren as 82 decibels of temperature.','The sound meter reported the siren as 82 decibels of sound level.','分贝用于表示声级等比值，不是温度单位。')],quiz:[Q('decibel',1,1,'A sound meter gives a reading of 65 decibels. What is being measured?',['sound level','air temperature','distance from the Moon'],'sound level','A decibel is a unit used to express sound level.'),Q('decibel',2,2,'Which reading would generally indicate the louder sound?',['95 decibels','20 decibels','both are identical by definition'],'95 decibels','A higher decibel level indicates greater sound intensity on the scale.'),Q('decibel',3,1,'A concert venue tracks noise in?',['decibels','litres','degrees Celsius'],'decibels','Decibels are used to measure sound levels.'),Q('decibel',4,2,'The prefix deci- in decibel means?',['one tenth','one thousand','two hundred'],'one tenth','The unit name combines deci-, meaning a tenth, with bel.') ]});
  D('deciduous',{etymology:E('deciduous comes from Latin deciduus, “falling off,” from decidere, “to fall down”; in botany it commonly describes trees that shed leaves seasonally.','deciduous'),contexts:[C('deciduous.s1','植物观察','The deciduous maples turned red in October, then stood bare through winter before growing fresh leaves in spring.','这些落叶枫树在十月变红，随后整个冬天枝叶凋尽，直到春天才长出新叶。','The deciduous maples turned red in October / then stood bare through winter / before growing fresh leaves in spring.','deciduous 作定语形容词；before 引出季节性落叶后的时间顺序。','枫树秋季落叶、春季再生，体现落叶树义。')],mistakes:[M('The evergreen tree was deciduous because it kept its leaves throughout every season.','The evergreen tree was not deciduous because it kept its leaves throughout every season.','全年保留叶子的常绿树不符合此处的季节性落叶义。')],quiz:[Q('deciduous',1,1,'A deciduous tree typically?',['loses its leaves seasonally','keeps all its leaves forever','produces sound in decibels'],'loses its leaves seasonally','Deciduous trees shed leaves, often in autumn.'),Q('deciduous',2,1,'Which plant is most likely deciduous?',['a maple that drops its leaves in fall','a pine that stays green year-round','a cactus with no seasonal leaf fall'],'a maple that drops its leaves in fall','The maple shows the seasonal leaf loss associated with deciduous trees.'),Q('deciduous',3,1,'When are deciduous branches often bare in a temperate climate?',['during winter after autumn leaf fall','during spring while leaves are newly growing','only while the tree is underwater'],'during winter after autumn leaf fall','Many deciduous trees shed leaves in autumn and remain bare over winter.'),Q('deciduous',4,1,'The opposite of deciduous in describing a tree is?',['evergreen','deceptive','decomposing'],'evergreen','Evergreen trees retain foliage rather than shedding it seasonally.') ]});
  D('decimation',{etymology:E('decimation comes from Latin decimatio, from decimare “to take a tenth”; in Roman military usage it referred to killing one soldier in every ten, and later broadened to severe destruction.','decimation'),contexts:[C('decimation.s1','生态保护','After the invasive disease spread, the decimation of the island’s seal population left only a small fraction of the animals alive.','入侵性疾病蔓延后，岛上海豹种群遭到大幅削减，只剩下很少一部分存活。','After the invasive disease spread / the decimation of the island’s seal population / left only a small fraction of the animals alive.','decimation 是名词，后接 of 引出被大幅削减的群体。','仅少数海豹存活，说明群体遭受严重损失。')],mistakes:[M('The decimation of the herd meant that every animal remained alive and the population doubled.','The recovery of the herd meant that every animal remained alive and the population doubled.','数量翻倍、无人死亡表示恢复增长，不是大幅毁灭或削减。')],quiz:[Q('decimation',1,1,'A disease kills most of a herd. The result is?',['the decimation of the herd','the decoration of the herd','the decompression of the herd'],'the decimation of the herd','Decimation means destruction or reduction of a large part of a group.'),Q('decimation',2,1,'Historically, Roman decimation involved killing?',['one soldier in every ten','all soldiers in a single unit','one soldier every ten years'],'one soldier in every ten','The original Roman punishment selected a tenth of the group.'),Q('decimation',3,1,'A report about the decimation of a forest describes?',['the destruction of a large proportion of it','a small change to its name','the planting of every missing tree'],'the destruction of a large proportion of it','Modern decimation often means severe loss or destruction.'),Q('decimation',4,1,'Which outcome best fits decimation?',['a population falls from 10,000 to 1,500','a population rises from 1,500 to 10,000','a population stays exactly the same'],'a population falls from 10,000 to 1,500','A severe reduction in numbers is decimation.') ]});
  D('decipher',{etymology:E('decipher combines de- with cipher; cipher reached English through French from Arabic sifr, “zero,” and came to mean a coded system or its symbols.','decipher'),contexts:[C('decipher.s1','历史档案','Researchers used the repeated symbols on the tablet to decipher a royal message whose code had resisted translation for centuries.','研究人员利用石板上重复出现的符号，破译了一封几个世纪以来都无法译解的王室密信。','Researchers used the repeated symbols / to decipher a royal message / whose code had resisted translation for centuries.','decipher + 宾语表示破译对象；whose 从句补充 message 的背景。','利用符号破解代码，符合密码破译义。'),C('decipher.s2','手写辨认','Even with a magnifying glass, Mei could barely decipher the doctor’s hurried handwriting on the old prescription.','即使拿着放大镜，小梅也几乎辨认不出旧处方上医生匆忙写下的字迹。','Even with a magnifying glass / Mei could barely decipher the doctor’s hurried handwriting / on the old prescription.','barely 表示勉强；handwriting 是 decipher 的宾语。','难以看清的字迹需要辨认，符合 s2。')],mistakes:[M('The archivist deciphered the sealed code by refusing to examine any of its symbols or patterns.','The archivist failed to decipher the sealed code because she never examined its symbols or patterns.','不查看任何线索就不能称为成功破译代码。')],quiz:[Q('decipher',1,1,'A linguist works out what a coded tablet says. The linguist?',['deciphers it','dehydrates it','decorates it'],'deciphers it','To decipher is to discover the meaning of coded writing.'),Q('decipher',2,2,'If you can barely decipher a note, you can barely?',['read or understand its unclear writing','hear its volume','change its temperature'],'read or understand its unclear writing','The verb also means to make out something difficult to read.'),Q('decipher',3,1,'Which task is an example of deciphering?',['breaking a substitution cipher','printing a blank page','measuring a room’s width'],'breaking a substitution cipher','A substitution cipher is a code whose message must be decoded.'),Q('decipher',4,2,'A doctor’s illegible note may be hard to?',['decipher','decimate','decouple'],'decipher','Here decipher means to read or interpret unclear writing.') ]});
  D('declivity',{etymology:E('declivity comes from Latin declivitas, from declivis “sloping downward”; it denotes a downward slope or the condition of descending.','declivity'),contexts:[C('declivity.s1','徒步路线','The hikers slowed as the narrow trail crossed a steep declivity, using their poles to keep their footing on the loose gravel.','徒步者经过陡峭的下坡时放慢脚步，用登山杖在松散的碎石上保持平衡。','The hikers slowed / as the narrow trail crossed a steep declivity / using their poles / to keep their footing on the loose gravel.','declivity 为名词，steep 修饰其坡面；as 引导原因/时间从句。','陡坡向下且碎石易滑，体现下坡地形义。')],mistakes:[M('The survey team called the uphill slope a declivity even though it rose sharply toward the summit.','The survey team called the uphill slope an incline because it rose sharply toward the summit.','declivity 特指向下倾斜的坡面；上升坡不能这样称呼。')],quiz:[Q('declivity',1,1,'A path descends sharply from the ridge. It crosses a?',['declivity','plateau','decor'],'declivity','A declivity is a downward-sloping surface.'),Q('declivity',2,2,'The declivity of a hill refers to?',['its downward slope or degree of descent','the number of trees on it','the sound it makes'],'its downward slope or degree of descent','The noun can describe the fact or degree of sloping downward.'),Q('declivity',3,1,'Which direction does a declivity slope?',['downward','upward','only sideways'],'downward','Declivity derives from a word meaning sloping downward.'),Q('declivity',4,1,'A cart rolls downhill along a steep declivity. What is steep?',['the downward slope','the cart’s color','the driver’s age'],'the downward slope','Declivity names the downward-sloping ground.') ]});
  D('decode',{etymology:E('decode is formed from de- plus code; the verb means to reverse a coding process or, figuratively, to interpret a hidden message.','decode'),contexts:[C('decode.s1','数据安全','The application can decode the backup file only after the user enters the correct key.','用户输入正确密钥后，应用程序才能解码备份文件。','The application can decode the backup file / only after the user enters the correct key.','decode 是及物动词，file 为其宾语；only after 强调前置条件。','密钥使编码文件还原为可读数据，符合 s1。'),C('decode.s2','社交理解','Nora learned to decode her colleague’s polite hints and realized that the deadline needed to be moved.','诺拉学会了解读同事礼貌的暗示，意识到截止日期需要调整。','Nora learned to decode her colleague’s polite hints / and realized / that the deadline needed to be moved.','decode hints 是比喻用法，表示理解言外之意。','她从委婉暗示中领会未明说的信息，符合 s2。')],mistakes:[M('The program decoded the file by converting readable data into an unreadable encrypted message.','The program encoded the file by converting readable data into an unreadable encrypted message.','把可读信息变成加密形式是 encode；decode 是反向还原。')],quiz:[Q('decode',1,1,'A receiver turns an encoded signal into readable text. The receiver?',['decodes the signal','dehydrates the signal','decorates the signal'],'decodes the signal','Decode means to turn coded information into an understandable form.'),Q('decode',2,2,'To decode a friend’s hint is to?',['understand its implied meaning','increase its volume','remove its punctuation only'],'understand its implied meaning','The verb can mean interpreting the hidden meaning of words or behavior.'),Q('decode',3,1,'Which action is decoding?',['using a key to read encrypted data','encrypting a plain message for storage','deleting a file without opening it'],'using a key to read encrypted data','Decoding reverses encryption so the data can be understood.'),Q('decode',4,2,'A manager decodes a vague response and understands the speaker’s reluctance. The manager?',['interprets what was implied','changes the response into a code','measures the response in decibels'],'interprets what was implied','The figurative sense is to understand hidden meaning.') ]});
  D('decolonization',{etymology:E('decolonization is formed from de- + colonization + -ation; colony comes from Latin colonia, “settlement,” and the modern political term names the ending of colonial rule.','decolonization'),contexts:[C('decolonization.s1','近代史','The course examines decolonization after the Second World War, tracing how former colonies negotiated independence and built new governments.','这门课程研究二战后的非殖民化，追溯前殖民地如何通过谈判获得独立并建立新政府。','The course examines decolonization after the Second World War / tracing how former colonies negotiated independence / and built new governments.','decolonization 为过程名词；后面的现在分词短语具体说明其历史内容。','殖民统治结束、殖民地走向独立，符合词义。')],mistakes:[M('Decolonization strengthened direct colonial control and permanently prevented the territory from governing itself.','Recolonization strengthened direct colonial control and prevented the territory from governing itself.','加强殖民控制与殖民地无法自治是再殖民化，不是结束殖民统治。')],quiz:[Q('decolonization',1,1,'When a colony gains independence and colonial rule ends, the process is?',['decolonization','decompression','deification'],'decolonization','Decolonization is the withdrawal of colonial rule and movement toward independence.'),Q('decolonization',2,1,'A history of decolonization would most directly discuss?',['former colonies becoming self-governing','the invention of a sound-measuring unit','the seasonal loss of leaves'],'former colonies becoming self-governing','The term describes political independence from colonial rule.'),Q('decolonization',3,1,'Which event is part of decolonization?',['a colonial administration transfers authority to an independent government','an empire expands its control over a new colony','a government bans every local election'],'a colonial administration transfers authority to an independent government','Transfer of governing authority ends colonial rule.'),Q('decolonization',4,1,'The prefix de- in decolonization signals?',['removal or reversal of colonial rule','a measurement of one tenth','a person who governs a colony'],'removal or reversal of colonial rule','The word names the process of ending colonization.') ]});
  D('decomposer',{etymology:E('decomposer is formed from decompose plus the agent suffix -er; it names an organism that breaks dead material into simpler substances.','decomposer'),contexts:[C('decomposer.s1','生态系统','On the forest floor, fungi acted as decomposers, breaking fallen leaves into nutrients that could return to the soil.','在森林地面上，真菌充当分解者，把落叶分解成可以回归土壤的养分。','On the forest floor / fungi acted as decomposers / breaking fallen leaves into nutrients / that could return to the soil.','decomposer 为施事名词；现在分词短语解释其生态作用。','真菌分解死亡植物并释放养分，符合分解者义。')],mistakes:[M('A decomposer made the dead leaves harder and stored them unchanged for decades.','A decomposer broke the dead leaves down into simpler substances and nutrients.','分解者会分解死物质，而不是使其保持不变并长期储存。')],quiz:[Q('decomposer',1,1,'Which organism can be a decomposer?',['a fungus that breaks down dead leaves','a rock that never changes','a living maple producing new leaves'],'a fungus that breaks down dead leaves','Fungi commonly act as decomposers of dead organic matter.'),Q('decomposer',2,1,'What does a decomposer do in an ecosystem?',['breaks dead material into simpler substances','turns sound into decibels','prevents all nutrients from cycling'],'breaks dead material into simpler substances','That breakdown returns materials to the ecosystem.'),Q('decomposer',3,1,'Bacteria feeding on dead organisms are examples of?',['decomposers','decorators','defenders'],'decomposers','Some bacteria perform the decomposer role.'),Q('decomposer',4,1,'Which food-web role is closest to a decomposer?',['recycling nutrients from dead matter','capturing sunlight as a leaf','hunting only living prey'],'recycling nutrients from dead matter','Decomposers break down dead matter and help recycle nutrients.') ]});
  D('decomposition',{etymology:E('decomposition derives from decompose, from de- “apart” and compose, ultimately Latin componere “put together”; it can mean chemical breakdown or decay of dead matter.','decomposition'),contexts:[C('decomposition.s1','化学实验','The chemist controlled the temperature because rapid decomposition of the unstable compound could release harmful gas.','化学家控制温度，因为这种不稳定化合物快速分解可能释放有害气体。','The chemist controlled the temperature / because rapid decomposition of the unstable compound / could release harmful gas.','decomposition of + 物质；because 引出控制温度的原因。','化合物拆解成较简单物质是化学分解义。'),C('decomposition.s2','土壤生态','Moist soil encouraged decomposition of the fallen branch, and insects and fungi gradually returned its nutrients to the ground.','潮湿土壤促进了落枝腐烂，昆虫和真菌逐渐把其中的养分还回地面。','Moist soil encouraged decomposition of the fallen branch / and insects and fungi gradually returned its nutrients to the ground.','decomposition 指死有机物的腐烂；后句说明其生态结果。','落枝被生物分解并回归土壤，符合 s2。')],mistakes:[M('The decomposition of the log left it completely unchanged and prevented any organisms from breaking it down.','The preservation of the log left it unchanged and prevented organisms from breaking it down.','保持原样是保存，不是物质逐渐分解或腐烂。')],quiz:[Q('decomposition',1,1,'When a chemical breaks into simpler substances, the process is?',['decomposition','decolonization','decoration'],'decomposition','Decomposition is the process of breaking a substance into simpler parts.'),Q('decomposition',2,2,'A dead leaf rots and returns nutrients to soil. This is?',['decomposition','compression','defiance'],'decomposition','The noun also refers to decay of dead plant or animal matter.'),Q('decomposition',3,1,'Which change shows decomposition?',['one compound separates into simpler products','two atoms combine into a larger molecule','a sample remains chemically unchanged'],'one compound separates into simpler products','Breaking a substance into simpler parts is decomposition.'),Q('decomposition',4,2,'A log gradually decays on the forest floor. What is occurring?',['decomposition','decryption','dehydration'],'decomposition','The word names decay of dead organic material.') ]});
  D('decompression',{etymology:E('decompression is formed from decompress plus -ion; decompress combines de- with compress, whose Latin source comprimere means “press together.” It can denote pressure release or mental relaxation.','decompression'),contexts:[C('decompression.s1','潜水安全','The diver followed the planned decompression stops on the ascent so that pressure changes would not injure the body.','潜水员上升时按计划停留减压，以免压力变化伤害身体。','The diver followed the planned decompression stops / on the ascent / so that pressure changes would not injure the body.','decompression stops 是潜水减压停留；so that 引出目的。','逐步降低潜水压力，符合物理减压义。'),C('decompression.s2','工作节奏','After a demanding week of negotiations, Luis took a quiet walk by the river as a period of decompression.','经历紧张的一周谈判后，路易斯在河边安静散步，让自己放松下来。','After a demanding week of negotiations / Luis took a quiet walk by the river / as a period of decompression.','decompression 可数地指精神紧张后的放松时段。','散步帮助缓解谈判带来的压力，符合 s2。')],mistakes:[M('The diver skipped all decompression stops after a deep dive because decompression requires pressure to rise as quickly as possible.','The diver followed the required decompression stops after a deep dive to reduce pressure safely.','减压是安全控制压力变化，不是让压力尽可能快地升高。')],quiz:[Q('decompression',1,1,'A diver pauses during ascent to avoid injury from changing pressure. These are?',['decompression stops','decorative breaks','decimation counts'],'decompression stops','The stops allow pressure to decrease safely.'),Q('decompression',2,2,'A quiet day after a stressful project can provide?',['decompression','deception','deciduous growth'],'decompression','The word can mean time to relax after mental pressure.'),Q('decompression',3,1,'A compressed file is restored to its original form through?',['decompression','decolonization','dehydration'],'decompression','The term also applies to releasing compressed data.'),Q('decompression',4,2,'Which person most clearly needs decompression?',['a negotiator relaxing after an intense week','a rested traveler before a holiday','a device being switched off'],'a negotiator relaxing after an intense week','A period of decompression follows mental strain.') ]});
  D('deconstruction',{etymology:E('deconstruction is formed from deconstruct plus -ion; deconstruct combines de- and construct, from Latin construere “to build.” In criticism it names analysis of a text’s tensions and assumptions.','deconstruction'),contexts:[C('deconstruction.s1','文学批评','In her essay, the critic offers a deconstruction of the novel’s hero, showing how his claims of fairness depend on excluding poorer characters.','评论家在文章中解构小说主人公，指出他关于公平的主张依赖于排斥更贫穷的人物。','In her essay / the critic offers a deconstruction of the novel’s hero / showing how his claims of fairness / depend on excluding poorer characters.','deconstruction of + 文本/观念；现在分词短语说明批评分析的发现。','分析揭示作品表面主张与内部矛盾，符合批评术语义。')],mistakes:[M('The article’s deconstruction simply repeated the novel’s stated message and ignored every contradiction in its language.','The article’s summary simply repeated the novel’s stated message and ignored contradictions in its language.','只复述表层信息而不分析内在矛盾是摘要，不是此处的解构性批评。')],quiz:[Q('deconstruction',1,1,'A critic reveals tensions beneath a text’s apparent claims. This is?',['deconstruction','decompression','deification'],'deconstruction','Deconstruction analyzes how a text can unsettle its apparent meanings.'),Q('deconstruction',2,1,'Which question best fits a deconstruction of a novel?',['What assumptions undermine the story’s stated values?','How many pages can be removed without changing the font?','What decibel level does the audiobook reach?'],'What assumptions undermine the story’s stated values?','The approach examines tensions and assumptions in a text.'),Q('deconstruction',3,1,'Deconstruction is most closely associated with?',['critical interpretation of texts','seasonal leaf loss','measuring sound intensity'],'critical interpretation of texts','The dictionary sense is a form of critical textual analysis.'),Q('deconstruction',4,1,'A paper compares a story’s claims with its contradictions. It offers?',['a deconstruction','a decibel','a decomposer'],'a deconstruction','The analysis looks beneath a text’s apparent meaning.') ]});
  D('decor',{etymology:E('decor entered English through French décor, from Latin decor “grace, beauty, or fitting ornament”; the modern noun refers to the style and furnishings of an interior.','decor'),contexts:[C('decor.s1','室内设计','The café’s decor pairs pale oak tables with green tiles, warm lamps, and framed photographs of the old harbour.','这家咖啡馆的装饰风格把浅色橡木桌、绿色瓷砖、暖色灯具和老港口照片搭配在一起。','The café’s decor pairs pale oak tables with green tiles / warm lamps / and framed photographs of the old harbour.','decor 是不可数名词，概括房间色彩、家具和装饰的整体风格。','句中列出家具、瓷砖和灯饰，体现室内布置义。')],mistakes:[M('The café’s decor referred only to its unpaid electricity bill and not to the appearance of the room.','The café’s decor referred to its furniture, colours, and other visible interior details.','账单不属于房间的装饰或布置风格。')],quiz:[Q('decor',1,1,'A room’s decor includes its?',['colours, furnishings, and decorative style','unpaid bills only','temperature record only'],'colours, furnishings, and decorative style','Decor describes how an interior is decorated and furnished.'),Q('decor',2,1,'A designer changes the curtains, lamps, and wall colour to update the?',['decor','decomposition','decimation'],'decor','Those visible choices shape the room’s decor.'),Q('decor',3,1,'Which phrase uses decor naturally?',['the hotel’s elegant decor','the decor of yesterday’s rainfall amount','a decor that means to measure sound'],'the hotel’s elegant decor','An interior’s overall style can be elegant decor.'),Q('decor',4,1,'A photo of a room shows its furniture and colour scheme. It documents the room’s?',['decor','decolonization','deference'],'decor','Decor refers to the appearance and furnishing of a room.') ]});
  D('decorative',{etymology:E('decorative comes from French décoratif or Latin decorativus, from decorare “to adorn”; it describes something intended chiefly to add visual appeal.','decorative'),contexts:[C('decorative.s1','家居用品','The ceramic bowl is decorative rather than practical: its narrow opening makes it unsuitable for serving soup.','这个陶瓷碗主要是装饰品而非实用品：碗口太窄，不适合盛汤。','The ceramic bowl is decorative rather than practical / its narrow opening makes it unsuitable for serving soup.','decorative rather than practical 对比装饰用途与实用功能。','碗主要供观赏，难以用于盛汤，符合 s1。'),C('decorative.s2','版面设计','A decorative border of small blue leaves framed each page without carrying any information from the report.','每页都用一圈蓝色小叶子作装饰边框，并不承载报告信息。','A decorative border of small blue leaves framed each page / without carrying any information from the report.','decorative 修饰 border，表示它只是改善页面外观。','边框用于点缀而非传递内容，符合 s2。')],mistakes:[M('The plain steel bracket hidden inside the wall was decorative because it had no visible design and served only to hold a beam.','The plain steel bracket hidden inside the wall was functional because it served to hold a beam.','隐蔽且承担支撑作用的部件主要是实用的，不是装饰性的。')],quiz:[Q('decorative',1,1,'A decorative bowl is made mainly to?',['look attractive','carry heavy liquid safely','measure room temperature'],'look attractive','Decorative describes an object made chiefly for appearance.'),Q('decorative',2,2,'A decorative border on a report page usually?',['adds visual appeal','contains the report’s full argument','supports the building roof'],'adds visual appeal','The border is added to improve appearance.'),Q('decorative',3,1,'Which item is most clearly decorative?',['a painted vase displayed empty on a shelf','a plain wrench used daily to tighten bolts','a hidden beam holding up a roof'],'a painted vase displayed empty on a shelf','The vase is displayed for its appearance.'),Q('decorative',4,2,'“Decorative rather than useful” emphasizes that an object?',['serves chiefly an ornamental purpose','is essential for its practical function','cannot be seen'],'serves chiefly an ornamental purpose','The phrase contrasts appearance with utility.') ]});
  D('decorator',{etymology:E('decorator is formed from decorate plus the agent suffix -or; decorate comes through French from Latin decorare, “to adorn.” The noun can name a painter or an interior-design professional.','decorator'),contexts:[C('decorator.s1','房屋翻新','The decorator filled the nail holes, painted the hallway, and hung new wallpaper before the family moved back in.','装饰工补好钉孔、粉刷走廊并贴上新墙纸，随后一家人才搬回来。','The decorator filled the nail holes / painted the hallway / and hung new wallpaper / before the family moved back in.','三个并列动作是 decorator 的墙面施工工作。','粉刷与贴墙纸对应室内油漆裱糊工义 s1。'),C('decorator.s2','家居规划','An interior decorator chose linen curtains and walnut shelves to make the narrow living room feel brighter.','室内装饰设计师选了亚麻窗帘和胡桃木架，让狭窄的客厅显得更明亮。','An interior decorator chose linen curtains and walnut shelves / to make the narrow living room feel brighter.','interior decorator 指规划室内色彩、家具和陈设的人。','搭配窗帘和书架改善空间视觉效果，符合设计师义。')],mistakes:[M('The decorator planned the room’s colours and furniture, but the job was described as delivering parcels door to door.','The decorator planned the room’s colours and furniture, while the courier delivered parcels door to door.','设计室内的工作是 decorator；运输包裹的是 courier。','confusable')],quiz:[Q('decorator',1,1,'A decorator who paints rooms and hangs wallpaper works mainly on?',['interior finishing','sound measurement','political elections'],'interior finishing','One sense names a person whose job is painting or wallpapering rooms.'),Q('decorator',2,2,'An interior decorator is hired to choose?',['colours and furniture for a room','the chemical formula of a wall','the decibel reading of a lamp'],'colours and furniture for a room','The design sense concerns planning an interior’s appearance.'),Q('decorator',3,1,'Which task best fits a decorator in the trade sense?',['painting a hallway','decoding a cipher','decimating a population'],'painting a hallway','Painting rooms is a decorator’s traditional job.'),Q('decorator',4,2,'The decorator selected rugs, lamps, and curtains to coordinate the room. This person is?',['an interior-design professional','a delivery driver','a decomposer'],'an interior-design professional','Selecting furnishings and colours fits the interior decorator sense.') ]});
  D('decorum',{etymology:E('decorum comes from Latin decorum, “what is proper or fitting,” from decere, “to be suitable”; it refers to polite, appropriate conduct, especially in formal settings.','decorum'),contexts:[C('decorum.s1','正式会议','The chair asked the audience to maintain decorum during the memorial service and to silence their phones.','主持人请观众在追思仪式上保持礼仪，并将手机调成静音。','The chair asked the audience / to maintain decorum during the memorial service / and to silence their phones.','maintain decorum 是固定搭配，指保持庄重得体的举止。','追思仪式需要安静、礼貌，体现正式场合礼仪义。')],mistakes:[M('The guests showed decorum at the solemn ceremony by shouting over the speaker and throwing food.','The guests showed a lack of decorum at the solemn ceremony by shouting over the speaker and throwing food.','喧闹和扔食物在庄严仪式上是失礼举动，而非得体行为。')],quiz:[Q('decorum',1,1,'At a formal ceremony, decorum means?',['proper and polite behavior','a sharp downward slope','a type of coded message'],'proper and polite behavior','Decorum is conduct suitable for a formal occasion.'),Q('decorum',2,2,'Shouting during a quiet memorial service would be?',['a breach of decorum','an example of decorum','a form of decomposition'],'a breach of decorum','The behavior is not proper or respectful in that setting.'),Q('decorum',3,1,'Which phrase is a natural collocation?',['observe decorum','decode decorum into bytes','measure decorum in litres'],'observe decorum','To observe decorum is to behave with proper manners.'),Q('decorum',4,2,'A calm, appropriate manner in public shows?',['decorum','deceit','decimation'],'decorum','The word can name the quality of behaving properly in public.') ]});
  D('decouple',{etymology:E('decouple is formed from de- plus couple; couple came through French from Latin copula, “a link or bond.” The verb means to disconnect things so they no longer depend on each other.','decouple'),contexts:[C('decouple.s1','经济政策','The reform aims to decouple housing subsidies from household income so that eligibility depends on need rather than salary alone.','这项改革旨在使住房补贴与家庭收入脱钩，让资格取决于实际需求，而非只看工资。','The reform aims to decouple housing subsidies from household income / so that eligibility depends on need / rather than salary alone.','decouple A from B 表示解除二者关联；so that 表目的。','补贴资格不再随收入联动，符合解除关联义。')],mistakes:[M('The policy decoupled electricity prices from fuel costs because each price continued to rise and fall in exact lockstep.','The policy failed to decouple electricity prices from fuel costs because they continued to move in lockstep.','完全同步变化说明两者仍然关联，没有脱钩。')],quiz:[Q('decouple',1,1,'A plan separates pay from years of service so neither determines the other. It aims to?',['decouple pay from seniority','decorate pay with seniority','decompose pay into leaves'],'decouple pay from seniority','To decouple is to remove a link or dependency.'),Q('decouple',2,1,'If two economic trends decouple, they?',['stop moving in a dependent relationship','become exactly the same measure','are combined into one trend'],'stop moving in a dependent relationship','Decoupling means one trend no longer depends on the other.'),Q('decouple',3,1,'Which sentence uses decouple correctly?',['The city decoupled water use from flat fees by charging by consumption.','The city decoupled two signals by making them permanently identical.','The city decoupled a wall by painting it blue.'],'The city decoupled water use from flat fees by charging by consumption.','The new billing method breaks the old relationship between use and a flat fee.'),Q('decouple',4,1,'In “decouple growth from emissions,” decouple means?',['make growth no longer tied to emissions','make emissions louder','make growth occur only in pairs'],'make growth no longer tied to emissions','The verb indicates removing a dependency between the two.') ]});
  D('decrepit',{etymology:E('decrepit came into English through French from Latin decrepitus, “worn out by age”; it describes something physically dilapidated or a person weakened by old age.','decrepit'),contexts:[C('decrepit.s1','老屋修缮','The tenants left the decrepit house after rain leaked through the roof and the rotten staircase began to sag.','屋顶漏雨、腐朽的楼梯开始下陷后，租户们搬离了这所破败不堪的房子。','The tenants left the decrepit house / after rain leaked through the roof / and the rotten staircase began to sag.','decrepit 修饰 house；漏雨和楼梯腐坏说明其破旧失修。','建筑濒临损坏，符合 s1。'),C('decrepit.s2','动物照护','The sanctuary moved the decrepit old donkey to a quiet paddock where a veterinarian could treat its weakness and joint pain.','动物庇护所把这头衰老虚弱的驴移到安静的围场，让兽医治疗它的虚弱和关节疼痛。','The sanctuary moved the decrepit old donkey / to a quiet paddock / where a veterinarian could treat its weakness and joint pain.','decrepit 描述因年老而衰弱；where 从句说明照护地点。','年迈且身体衰弱，体现 s2。')],mistakes:[M('The newly built bridge was decrepit, with perfect concrete, no cracks, and every inspection confirming it was sound.','The abandoned bridge was decrepit, with cracked concrete and a deck that was no longer safe.','崭新、完好并通过检查的桥不可能是破败不堪的。')],quiz:[Q('decrepit',1,1,'A house with rotten stairs and a leaking roof is?',['decrepit','decorative','deciduous'],'decrepit','The building is worn out and falling into disrepair.'),Q('decrepit',2,2,'A person weakened by advanced age may be described as?',['decrepit','deceptive','decoupled'],'decrepit','The adjective also describes weakness caused by old age.'),Q('decrepit',3,1,'Which object is most likely decrepit?',['an abandoned bus with rusted panels and failing brakes','a new bus with a valid inspection','a clean bus just delivered from the factory'],'an abandoned bus with rusted panels and failing brakes','The abandoned vehicle is worn out and in poor condition.'),Q('decrepit',4,2,'The word decrepit emphasizes?',['serious physical decline from age or neglect','an attractive interior design','a hidden code'],'serious physical decline from age or neglect','Both the aged-person and dilapidated-object senses involve severe decline.') ]});
  D('decry',{etymology:E('decry entered English through French décrier, from Old French cri “cry out”; it came to mean publicly condemning or disparaging something.','decry'),contexts:[C('decry.s1','公共政策','Local residents decried the proposal to close the clinic, arguing that the nearest alternative was an hour away.','当地居民公开谴责关闭诊所的提议，指出最近的替代诊所也要一小时车程。','Local residents decried the proposal to close the clinic / arguing that the nearest alternative was an hour away.','decry + 宾语表示公开谴责；现在分词短语交代理由。','居民强烈公开反对该提议，符合 s1。'),C('decry.s2','艺术评论','The reviewer decried the new mural as a cheap imitation, claiming that it had little artistic value.','评论家贬低这幅新壁画是廉价仿作，声称它几乎没有艺术价值。','The reviewer decried the new mural as a cheap imitation / claiming that it had little artistic value.','decry A as B 表示把A贬斥为B。','评论者说壁画毫无价值，对应贬低义。')],mistakes:[M('The editorial decried the policy by celebrating it as a wise and universally beneficial reform.','The editorial praised the policy as a wise and broadly beneficial reform.','庆祝并肯定政策，不是公开谴责或贬低它。')],quiz:[Q('decry',1,1,'Residents publicly condemned a plan. They?',['decried it','decorated it','decoded it'],'decried it','To decry something is to express strong public disapproval.'),Q('decry',2,2,'A critic says a design has almost no value and calls it a failure. The critic?',['decries the design','decompresses the design','defaces the design'],'decries the design','The verb can mean to say that something is of little value.'),Q('decry',3,1,'Which action best fits decry?',['speaking out strongly against a proposed law','quietly measuring a proposed law','printing a proposed law in blue'],'speaking out strongly against a proposed law','Decry commonly describes public condemnation.'),Q('decry',4,2,'“The columnist decried the film as shallow” means the columnist?',['dismissed it as having little merit','praised its subtle depth','decoded its soundtrack'],'dismissed it as having little merit','Here decried means disparaged or criticized as worthless.') ]});
  D('dedicated',{etymology:E('dedicated is the past participle and adjective of dedicate, from Latin dedicare “to set apart or consecrate”; it can describe committed people or something reserved for one use.','dedicated'),contexts:[C('dedicated.s1','科研工作','The dedicated nurses stayed after their shifts to help families understand the treatment plan.','尽职投入的护士们下班后仍留下来，帮助家属理解治疗方案。','The dedicated nurses stayed after their shifts / to help families understand the treatment plan.','dedicated 修饰人，表示认真投入、关心工作的特质。','下班后继续帮助病患家属，体现奉献投入义 s1。'),C('dedicated.s2','设备配置','The lab has a dedicated freezer for vaccine samples, so food and research materials are stored separately.','实验室有一台专门存放疫苗样本的冰柜，因此食品和研究材料分开保存。','The lab has a dedicated freezer for vaccine samples / so food and research materials are stored separately.','dedicated + 名词表示设备被指定作某一用途。','冰柜留给疫苗样本单独使用，符合 s2。')],mistakes:[M('The dedicated sample freezer was used indiscriminately for lunch, drinks, and every unrelated household item.','The general-purpose freezer was used for lunch, drinks, and other household items.','不专用于某一用途的设备不宜称 dedicated freezer。')],quiz:[Q('dedicated',1,1,'A nurse who works with care because patients matter is?',['dedicated','decrepit','deceptive'],'dedicated','The adjective describes someone committed to a purpose.'),Q('dedicated',2,2,'A dedicated printer in an office is?',['set aside for a particular use','too old to work','designed to measure sound'],'set aside for a particular use','The equipment sense means reserved for one specific purpose.'),Q('dedicated',3,1,'Which action shows a dedicated volunteer?',['returning regularly to support the community project','forgetting every scheduled shift','joining only to disrupt the work'],'returning regularly to support the community project','Consistent effort for a cause shows commitment.'),Q('dedicated',4,2,'A dedicated line between two computers is a line?',['reserved specifically for their connection','open to unrelated traffic only','painted as decoration'],'reserved specifically for their connection','Dedicated can describe a resource allocated to one use.') ]});
  D('dedication',{etymology:E('dedication comes from dedicate plus the noun-forming suffix -ion, from Latin dedicatio; it can mean committed effort or a short inscription offering a book to someone.','dedication'),contexts:[C('dedication.s1','社区服务','The restoration succeeded through years of dedication from volunteers who met every weekend to repair the old library.','在多年志愿者的全心投入下，修复工程终于成功；他们每周末都来修缮这座老图书馆。','The restoration succeeded through years of dedication from volunteers / who met every weekend / to repair the old library.','dedication from + 人表示其长期投入；who 从句说明行动。','坚持多年定期参与体现奉献精神义 s1。'),C('dedication.s2','书籍扉页','The novel opens with a dedication to the author’s grandmother, whose stories inspired its central character.','小说开篇有一段献给作者祖母的献辞，她讲的故事启发了书中的主人公。','The novel opens with a dedication to the author’s grandmother / whose stories inspired its central character.','a dedication to sb 是题献的常见表达。','置于书前献给某人的文字对应 s2。')],mistakes:[M('The book dedication credited to the author’s grandmother appeared only in a private tax form and not in the book.','The book dedication to the author’s grandmother appeared on a page near the front of the book.','书前题献是献辞；私人税表不是书籍 dedication。')],quiz:[Q('dedication',1,1,'Years of careful volunteer work demonstrate?',['dedication','defection','decomposition'],'dedication','Dedication is sustained effort and loyalty toward a goal.'),Q('dedication',2,2,'A short note offering a book to someone is its?',['dedication','decryption key','decibel rating'],'dedication','A book dedication names the person to whom the author offers it.'),Q('dedication',3,1,'Which phrase best describes dedication to a cause?',['steady hard work over many years','a single accidental glance','a change of font size'],'steady hard work over many years','Long-term effort reflects the commitment sense.'),Q('dedication',4,2,'Where would you most likely find a dedication in a novel?',['near the front, before the main text','on the back of a bus ticket','inside a freezer'],'near the front, before the main text','Book dedications are usually printed at the beginning.') ]});
  D('deduction',{etymology:E('deduction comes through French from Latin deductio, from deducere “lead down or derive”; English uses it for an amount subtracted and a conclusion reasoned from general facts.','deduction'),contexts:[C('deduction.s1','工资单','After the insurance deduction, the employee’s take-home pay was lower than the gross salary shown at the top of the statement.','扣除保险费后，员工的实发工资低于工资单顶部所列的税前工资。','After the insurance deduction / the employee’s take-home pay was lower / than the gross salary shown at the top of the statement.','deduction 作扣款名词；after 引出减项产生的结果。','保险费从工资总额中扣除，对应 s1。'),C('deduction.s2','逻辑推理','By deduction, the detective concluded that the key had to belong to one of the three people who entered after noon.','经过演绎推理，侦探得出结论：钥匙必定属于中午后进入的三个人之一。','By deduction / the detective concluded / that the key had to belong to one of the three people / who entered after noon.','by deduction 表示运用推理；that 从句说明结论。','从已知进入时间推出可能归属，符合 s2。')],mistakes:[M('The tax deduction raised the worker’s taxable income by adding an extra charge to the salary.','The tax deduction lowered the worker’s taxable income by subtracting an allowed amount.','扣除额会减去部分金额，而不是增加应税收入。')],quiz:[Q('deduction',1,1,'An amount taken from gross pay is a?',['deduction','dedication','decimation'],'deduction','A deduction is an amount subtracted from a total, such as pay.'),Q('deduction',2,2,'Reasoning from a general rule to a specific conclusion is?',['deduction','decoration','dehydration'],'deduction','The logical sense derives a conclusion from general principles.'),Q('deduction',3,1,'If a tax deduction is $500, the amount is?',['subtracted under the applicable tax rules','added to the tax bill as a penalty','a measure of sound'],'subtracted under the applicable tax rules','A deduction is an amount taken away from a total.'),Q('deduction',4,2,'A detective uses known facts to infer who had access. This is?',['deductive reasoning','a wage deduction','decompression'],'deductive reasoning','The conclusion is reached by reasoning from available premises.') ]});
  D('deductive',{etymology:E('deductive is formed from deduction or deduct plus -ive; it describes reasoning that proceeds from a general rule or premise to a specific conclusion.','deductive'),contexts:[C('deductive.s1','科学方法','The researcher used deductive reasoning: if every sample of the compound reacts to heat, this sample should react when warmed.','研究者运用演绎推理：如果这种化合物的每份样品遇热都会反应，那么这份样品加热后也应反应。','The researcher used deductive reasoning / if every sample of the compound reacts to heat / this sample should react when warmed.','deductive reasoning 从一般前提推到具体样本。','从普遍规律推出单个样品预期结果，符合 s1。'),C('deductive.s2','逻辑训练','The class practiced a deductive argument by checking whether its conclusion followed from each stated premise.','全班练习演绎论证，检查结论是否能从每个明示前提中推出。','The class practiced a deductive argument / by checking whether its conclusion followed from each stated premise.','deductive 修饰 argument，强调按逻辑步骤得出结论。','逐项检查前提与结论间的推导关系，符合 s2。')],mistakes:[M('The argument was deductive because it guessed a broad rule from two unusual examples and offered no general premise.','The argument was inductive because it generalized from a few examples without a stated general premise.','由少数例子归纳出概括性规律是归纳，不是从一般前提演绎到个例。')],quiz:[Q('deductive',1,1,'Reasoning from a general rule to a particular case is?',['deductive','decorative','defiant'],'deductive','Deductive reasoning applies a general principle to a specific fact.'),Q('deductive',2,2,'A conclusion reached through linked logical steps is?',['deductive','deciduous','decomposing'],'deductive','The adjective can describe a conclusion reached by logical reasoning.'),Q('deductive',3,1,'Which is a deductive pattern?',['All metals expand when heated; iron is a metal; therefore iron expands when heated.','Several swans are white; therefore every bird is white.','The result is chosen before any premise is given.'],'All metals expand when heated; iron is a metal; therefore iron expands when heated.','A general premise is applied to a particular instance.'),Q('deductive',4,2,'A deductive argument should have a conclusion that?',['follows logically from its premises','is unrelated to every premise','depends only on a random guess'],'follows logically from its premises','Deductive reasoning draws a conclusion through logical steps.') ]});
  D('deepen',{etymology:E('deepen is formed from deep plus the verb-forming suffix -en; it can mean to become more physically deep or make feelings, knowledge, or colour more intense.','deepen'),contexts:[C('deepen.s1','河道工程','The channel began to deepen after months of strong currents washed sediment away from its centre.','强劲水流冲走河道中央的泥沙数月后，河道开始变深。','The channel began to deepen / after months of strong currents / washed sediment away from its centre.','deepen 作不及物动词，表示深度增加。','河床泥沙被冲走，水道深度随之增加，符合本义。')],mistakes:[M('The shallow pond deepened when workers filled it with gravel until only a few centimetres of water remained.','The shallow pond became shallower when workers filled it with gravel until only a few centimetres of water remained.','填入砾石减少水深，不能说池塘 deepened。')],quiz:[Q('deepen',1,1,'If a river channel deepens, it?',['becomes more deep','becomes wider but stays equally shallow','turns into a dry road'],'becomes more deep','Deepen means to become deeper or make something deeper.'),Q('deepen',2,1,'Which action would deepen a well?',['digging its bottom farther down','filling it with stones','covering it with a lid'],'digging its bottom farther down','Removing more earth increases the well’s depth.'),Q('deepen',3,1,'A blue paint colour deepens when it becomes?',['richer or more intense','paler and less saturated','completely transparent'],'richer or more intense','The verb can describe colour becoming more intense.'),Q('deepen',4,1,'Which relationship can deepen over time?',['a friendship becoming closer','a paper becoming thinner by cutting','a code changing into plain text'],'a friendship becoming closer','Figuratively, deepen can mean make a feeling or relationship stronger.') ]});
  D('deface',{etymology:E('deface entered English through Anglo-French desfacier, from des- plus face; it means to spoil the appearance of an object or surface.','deface'),contexts:[C('deface.s1','公共文物','Security footage showed someone trying to deface the stone memorial with spray paint before a guard intervened.','监控录像显示有人试图用喷漆污损石碑纪念物，随后保安及时制止。','Security footage showed someone trying to deface the stone memorial / with spray paint / before a guard intervened.','deface + 物体作宾语，with 引出污损所用工具。','喷漆破坏纪念碑外观，符合词义。')],mistakes:[M('The conservator defaced the inscription by cleaning away the graffiti and restoring the original stone letters.','The conservator restored the inscription by cleaning away the graffiti and repairing the original stone letters.','清除涂鸦、恢复原貌是修复，不是破坏外观。')],quiz:[Q('deface',1,1,'Someone spray-paints a historic monument. The person tries to?',['deface it','decompress it','dedicate it'],'deface it','To deface is to damage the appearance of a building, book, or monument.'),Q('deface',2,1,'Which action would deface a library book?',['scribbling across its cover','placing it carefully on a shelf','repairing a torn page'],'scribbling across its cover','The scribble spoils the book’s appearance.'),Q('deface',3,1,'A clean wall is covered in unwanted graffiti. The wall has been?',['defaced','deepened','decoded'],'defaced','Unwanted markings can damage a surface’s appearance.'),Q('deface',4,1,'Choose a synonym for deface in “deface public property.”',['mar','polish','protect'],'mar','Deface means to spoil or damage the visible surface.') ]});
  D('defame',{etymology:E('defame came through French from Latin diffamare, “spread an evil report about,” from dis- and fama “report or reputation”; it means damaging a person’s good name with false statements.','defame'),contexts:[C('defame.s1','法律与名誉','The court heard whether the false online post was published to defame the restaurant owner and damage her professional reputation.','法院审理这则虚假网帖是否意在诽谤餐馆老板、损害她的职业声誉。','The court heard whether the false online post / was published to defame the restaurant owner / and damage her professional reputation.','defame + 人作宾语，后接损害名誉的目的。','虚假言论意图损害个人声誉，符合诽谤义 s1。'),C('defame.s2','公共言论','A rival tried to defame the candidate in public by repeating an untrue story about his private conduct.','竞争对手反复散布有关候选人私生活的不实传闻，试图当众中伤他。','A rival tried to defame the candidate in public / by repeating an untrue story / about his private conduct.','in public 与 by 短语分别说明场合和手段。','当众散布虚假说法攻击名誉，对应 s2。')],mistakes:[M('The verified report defamed the witness by accurately quoting her public statement without adding any false claim.','The verified report quoted the witness accurately without defaming her.','准确转述公开言论且没有虚假指控，不构成诽谤。')],quiz:[Q('defame',1,1,'Publishing a false claim to ruin someone’s reputation is to?',['defame that person','deepen that person','decompose that person'],'defame that person','Defame means to damage a person’s good name with false statements.'),Q('defame',2,2,'A rival publicly spreads an untrue story to harm a candidate’s reputation. The rival?',['defames the candidate','decorates the candidate','decodes the candidate'],'defames the candidate','The public attack on the good name illustrates the second sense.'),Q('defame',3,1,'Which statement best fits defame?',['A false accusation is circulated to damage a person’s standing.','A verified fact is reported without insult.','A private opinion is kept to oneself.'],'A false accusation is circulated to damage a person’s standing.','False damaging claims are central to defamation.'),Q('defame',4,2,'To defame someone in public is to?',['attack their good name before others','repair their damaged reputation','deduct money from their wages'],'attack their good name before others','The verb can describe public attacks on someone’s reputation.') ]});
  D('defecate',{etymology:E('defecate comes from Latin defaecare, “to cleanse or strain off impurities,” from de- and faex “dregs”; in modern English it means to empty the bowels.','defecate'),contexts:[C('defecate.s1','动物健康','The veterinarian asked the owner to note how often the dog defecated and whether its stool had changed in colour.','兽医请主人记录狗排便的频率，以及粪便颜色是否有变化。','The veterinarian asked the owner / to note how often the dog defecated / and whether its stool had changed in colour.','defecate 是医学与动物护理中较正式的动词。','记录排便频率和粪便变化，符合排便义。')],mistakes:[M('The patient was unable to defecate, so the nurse recorded that the bowels had emptied normally.','The patient was able to defecate, so the nurse recorded that the bowels had emptied normally.','无法排便与肠道已正常排空相矛盾。')],quiz:[Q('defecate',1,1,'In a clinical note, defecate means to?',['empty the bowels','lower air pressure','decorate a room'],'empty the bowels','Defecate is the formal verb for passing stool.'),Q('defecate',2,1,'Which sentence uses defecate correctly?',['The animal defecated shortly after eating.','The animal defecated the water into steam.','The animal defecated the wall blue.'],'The animal defecated shortly after eating.','The verb is intransitive and refers to emptying the bowels.'),Q('defecate',3,1,'A vet asks about how often a pet defecates to learn about its?',['bowel movements','hearing range','coat colour only'],'bowel movements','Frequency of defecation concerns bowel function.'),Q('defecate',4,1,'Which is the closest plain-language meaning of defecate?',['pass stool','speak loudly','remove a code'],'pass stool','The formal medical meaning is to empty the bowels.') ]});
  D('defection',{etymology:E('defection comes from Latin defectio, from deficere “fail or desert”; it can name abandoning one’s side or a deficiency in something.','defection'),contexts:[C('defection.s1','政党新闻','The minister’s defection to the opposition changed the balance of votes in parliament.','这位部长转投反对党，改变了议会中的票数平衡。','The minister’s defection to the opposition / changed the balance of votes in parliament.','defection to + 阵营说明背弃原有一方并转投另一方。','部长离开原党加入对立阵营，符合 s1。'),C('defection.s2','系统缺陷','The safety review found a defection in the backup process: no copy was made when the main server failed.','安全审查发现备份流程有缺陷：主服务器故障时系统没有生成副本。','The safety review found a defection in the backup process / no copy was made / when the main server failed.','defection 的 s2 表示缺点或缺失，但此义较少见。','备份所需环节缺失，使用词条列出的缺陷义。')],mistakes:[M('The senator’s defection to the rival party meant she remained loyal to her original party and never changed sides.','The senator’s defection to the rival party meant she left her original party and changed sides.','转投对立阵营表示背叛原有立场，不可能同时始终留在原党。')],quiz:[Q('defection',1,1,'A politician leaves one party and joins its rival. This move is a?',['defection','dedication','decomposition'],'defection','Defection is leaving one side to join an opposing one.'),Q('defection',2,2,'A report uses defection to mean a fault or missing feature. It describes?',['a deficiency','a book inscription','a public ceremony'],'a deficiency','The less common sense is a fault or lack of something needed.'),Q('defection',3,1,'Which event best illustrates defection?',['an officer abandons one force and joins the opposing side','a player remains loyal to the same team','a committee prints its annual report'],'an officer abandons one force and joins the opposing side','Changing allegiance to the opposing side is defection.'),Q('defection',4,2,'A defect in a process may be described, in the listed sense, as a?',['defection','decibel','decorator'],'defection','The noun can also mean a fault or lack of something needed.') ]});
  D('defective',{etymology:E('defective comes from defect plus -ive; defect is from Latin defectus, “a failing or deficiency.” The adjective describes something faulty, and the noun can refer to a faulty item.','defective'),contexts:[C('defective.s1','产品检验','The factory recalled the defective kettle after inspectors found that its power switch could overheat and melt the casing.','检查人员发现电水壶的电源开关可能过热并熔化外壳后，工厂召回了这批有缺陷的产品。','The factory recalled the defective kettle / after inspectors found / that its power switch could overheat / and melt the casing.','defective 修饰产品；after 引出召回原因。','开关无法安全工作，符合有缺陷义 s1。'),C('defective.s2','退货管理','The store placed each defective in a marked returns bin so staff could inspect and replace the faulty item.','商店把每件瑕疵品放进标记清楚的退货箱，方便员工检查并更换。','The store placed each defective in a marked returns bin / so staff could inspect and replace the faulty item.','defective 作名词指有缺陷的物品，实际使用时常见于行业语境。','退回并待检查的故障商品对应名词义 s2。')],mistakes:[M('The inspector labelled the kettle defective even though every switch worked safely in repeated tests and no flaw was found.','The inspector labelled the kettle reliable after every switch passed repeated safety tests.','多次测试正常且未发现故障，不支持称产品有缺陷。')],quiz:[Q('defective',1,1,'A kettle overheats because its switch is faulty. The kettle is?',['defective','dedicated','decorative'],'defective','A defective product does not work as it should.'),Q('defective',2,2,'A retailer sorts faulty returned goods into a box marked “defectives.” Here defectives are?',['faulty items','store employees','product instructions'],'faulty items','The noun can refer to goods that are defective.'),Q('defective',3,1,'Which result most clearly shows a defective part?',['a switch fails under normal use','a switch passes all safety tests','a switch is stored unused'],'a switch fails under normal use','Failure during normal operation shows the part is faulty.'),Q('defective',4,2,'The product was rejected as defective because it?',['had a fault that prevented proper operation','was reserved for a special use','was offered at a discount'],'had a fault that prevented proper operation','Defective means made or functioning incorrectly.') ]});
  D('defender',{etymology:E('defender comes from Old French defendre, from Latin defendere, “ward off or protect”; the agent noun names a protector, a sports player, or someone who supports a person or idea.','defender'),contexts:[C('defender.s1','足球比赛','The defender intercepted the pass before it reached the striker and cleared the ball away from the goal.','后卫在传球到达前锋脚下前将球截下，并把球踢离球门。','The defender intercepted the pass / before it reached the striker / and cleared the ball away from the goal.','defender 在体育语境指防守队员；intercept、clear 是其动作。','保护球门并阻止对手进攻，体现 s1。'),C('defender.s2','公共辩论','A defender of the proposal argued that its safeguards would protect small businesses from sudden cost increases.','该提案的一位支持者认为，提案中的保障措施能保护小企业免受成本突然上涨的影响。','A defender of the proposal argued / that its safeguards would protect small businesses / from sudden cost increases.','a defender of + 观点/人物表示支持并为其辩护的人。','公开为提案辩护支持，符合 s2。')],mistakes:[M('The defender of the proposal argued against it at every meeting and urged the committee to reject it.','The opponent of the proposal argued against it at every meeting and urged the committee to reject it.','持续反对提案的人是 opponent，而不是支持提案的 defender。')],quiz:[Q('defender',1,1,'In soccer, a defender mainly tries to?',['stop opponents from scoring','score only by serving the ball','measure the field’s decibels'],'stop opponents from scoring','A defender protects the goal or defensive area.'),Q('defender',2,2,'A defender of a policy is someone who?',['speaks in support of it','leaves to join the opposition','damages its public reputation'],'speaks in support of it','The second sense is a person who argues in favor of an idea.'),Q('defender',3,1,'Which action is most typical of a defender in football?',['blocking an opponent’s attack','writing a book dedication','repairing a roof'],'blocking an opponent’s attack','Defenders protect their side from attacks.'),Q('defender',4,2,'The phrase “a defender of free speech” refers to a person who?',['supports and argues for free speech','opposes every discussion','measures speech in units'],'supports and argues for free speech','A defender can advocate for a principle.') ]});
  D('defenseless',{etymology:E('defenseless is formed from defense plus -less, “without”; it means lacking protection against attack or harm. British English commonly spells the noun defence, while the adjective is also defenseless/defenceless.','defenseless'),contexts:[C('defenseless.s1','灾害救援','Without the levee, the low-lying village was defenseless against the seasonal floods that swept across the plain.','没有堤坝保护，这座低洼村庄面对席卷平原的季节性洪水毫无防护能力。','Without the levee / the low-lying village was defenseless / against the seasonal floods / that swept across the plain.','defenseless against + 威胁表示缺乏抵御手段。','洪水面前缺少堤坝保护，符合无防备义。')],mistakes:[M('The fortified shelter was defenseless against storms because thick walls, a roof, and emergency barriers fully protected it.','The fortified shelter was well protected against storms because its walls, roof, and barriers provided defenses.','坚固防护齐全的避难所不符合毫无防御的意思。')],quiz:[Q('defenseless',1,1,'A village with no barriers against flooding is?',['defenseless','defensive','deductive'],'defenseless','It lacks protection against the flood threat.'),Q('defenseless',2,1,'Which person is most defenseless in the described situation?',['a hiker without shelter in a severe storm','a pilot inside a reinforced aircraft','a soldier behind a protected wall'],'a hiker without shelter in a severe storm','The hiker lacks protection from the storm.'),Q('defenseless',3,1,'If an argument is defenseless against criticism, it?',['has no strong support to answer the criticism','has several robust supporting reasons','has been protected by a lawyer'],'has no strong support to answer the criticism','Figuratively, defenseless means unable to withstand attack or challenge.'),Q('defenseless',4,1,'Choose the closest opposite of defenseless.',['protected','exposed','unshielded'],'protected','Being protected is the opposite of having no defense.') ]});
  D('defensible',{etymology:E('defensible is formed from defend plus -ible, “capable of”; it means capable of being justified by reasons or protected from attack.','defensible'),contexts:[C('defensible.s1','学术论证','The researcher offered a defensible interpretation of the results and showed how each conclusion followed from the data.','研究者提出了站得住脚的结果解释，并说明每个结论如何由数据推出。','The researcher offered a defensible interpretation of the results / and showed / how each conclusion followed from the data.','defensible 修饰 interpretation，强调有证据或理由可支持。','逐项以数据支持结论，符合可辩护义 s1。'),C('defensible.s2','军事地理','The narrow ridge was defensible because cliffs protected both sides and only one path led to the summit.','这条狭窄山脊易守难攻，因为两侧有峭壁保护，只有一条小路通往山顶。','The narrow ridge was defensible / because cliffs protected both sides / and only one path led to the summit.','defensible 作表语形容词，表示位置能够防守。','峭壁和单一入口提供防御优势，符合 s2。')],mistakes:[M('The conclusion was defensible although its author supplied no evidence, ignored contrary data, and could not explain the reasoning.','The conclusion was indefensible because its author supplied no evidence and could not explain the reasoning.','完全没有证据且无法说明推理，结论就缺乏可辩护性。')],quiz:[Q('defensible',1,1,'An interpretation supported by evidence is?',['defensible','defenseless','deceptive'],'defensible','It can be supported with reasons and evidence.'),Q('defensible',2,2,'A hilltop with protected approaches is defensible because it?',['can be protected against attack','cannot be reached by any route','has no possible defenses'],'can be protected against attack','The adjective also describes a position that can be defended.'),Q('defensible',3,1,'Which expense is most defensible in a budget review?',['one justified by documented need','one with no explanation or record','one that contradicts the approved plan'],'one justified by documented need','A defensible choice can be supported with reasons.'),Q('defensible',4,2,'A fortress is described as defensible. This means?',['its position can be protected against attack','it has already been destroyed','it is meant only for decoration'],'its position can be protected against attack','The physical sense concerns being capable of defense.') ]});
  D('defensive',{etymology:E('defensive comes through French from Latin defensivus, from defendere “ward off”; it can describe protection or a touchy reaction to perceived criticism.','defensive'),contexts:[C('defensive.s1','体育战术','The team shifted to a defensive formation after taking the lead, placing more players between the opponents and the goal.','领先后，球队改用防守阵型，在对手和球门之间安排了更多队员。','The team shifted to a defensive formation / after taking the lead / placing more players / between the opponents and the goal.','defensive 修饰 formation，表示以抵御进攻为目的。','布置球员阻止对手得分，符合防御义 s1。'),C('defensive.s2','日常沟通','When her colleague asked about the missed deadline, Priya became defensive and immediately blamed the software.','同事询问错过截止日期的原因时，普丽娅变得戒备易恼，立刻把责任推给软件。','When her colleague asked about the missed deadline / Priya became defensive / and immediately blamed the software.','become defensive 表示因觉得受批评而戒备或易恼。','面对质问马上推责，体现 s2。')],mistakes:[M('He was defensive during the review because he welcomed every question calmly and never felt accused or criticized.','He was open and receptive during the review because he welcomed every question calmly.','平静接纳问题、没有感到受指责，不符合易戒备易恼的义项。')],quiz:[Q('defensive',1,1,'A defensive line of players is positioned to?',['protect against an opposing attack','decorate the playing field','leave the goal unguarded'],'protect against an opposing attack','The adjective describes a formation intended for protection.'),Q('defensive',2,2,'Someone who reacts angrily to ordinary questions may be?',['defensive','deferential','dedicated'],'defensive','The personal sense is too ready to feel criticized.'),Q('defensive',3,1,'Which plan is defensive?',['adding barriers to protect a site','removing all safeguards from a site','publishing a dedication to a site'],'adding barriers to protect a site','A defensive action is intended to prevent harm or attack.'),Q('defensive',4,2,'“She sounded defensive” most likely means she?',['seemed to take the question as criticism','was calmly curious about the answer','was physically protected by a wall'],'seemed to take the question as criticism','The figurative sense describes a touchy response to perceived criticism.') ]});
  D('deference',{etymology:E('deference comes from French déférence, from déférer, “yield or defer,” ultimately Latin deferre; it names respectful regard or willingness to accept another person’s judgment.','deference'),contexts:[C('deference.s1','学术讨论','In deference to the senior scientist’s experience, the team reviewed her safety concerns before beginning the trial.','出于对资深科学家经验的尊重，团队在开始试验前先审查了她提出的安全顾虑。','In deference to the senior scientist’s experience / the team reviewed her safety concerns / before beginning the trial.','in deference to + 人或意见，表示出于尊重而考虑或顺从。','团队因尊重其经验而认真审查建议，符合 s1。'),C('deference.s2','机构决策','The committee showed deference to the local judge’s ruling and delayed its own decision.','委员会听从当地法官的裁决，推迟了自己的决定。','The committee showed deference to the local judge’s ruling / and delayed its own decision.','show deference to + 裁决表示愿意接受他人的决定。','委员会依从法官裁决，符合 s2。')],mistakes:[M('The junior officer showed deference to the commander by openly rejecting every instruction and refusing to listen.','The junior officer showed defiance toward the commander by openly rejecting every instruction.','公开拒绝命令是 defiance（违抗），与尊重、听从相反。','confusable')],quiz:[Q('deference',1,1,'A team carefully considers an expert’s advice out of respect. It shows?',['deference','defiance','decomposition'],'deference','Deference is polite regard for someone with greater knowledge or status.'),Q('deference',2,2,'A board accepts a judge’s decision instead of overriding it. The board shows?',['deference','defacement','dehydration'],'deference','This illustrates willingness to accept another person’s decision.'),Q('deference',3,1,'The phrase “in deference to the safety officer” means?',['out of respect for the safety officer','in open opposition to the safety officer','without knowing the safety officer'],'out of respect for the safety officer','The phrase marks respectful consideration.'),Q('deference',4,2,'Which behavior best shows deference?',['listening respectfully and yielding to a qualified decision','mocking the decision and refusing to hear it','damaging the decision-maker’s property'],'listening respectfully and yielding to a qualified decision','Deference involves respect and readiness to accept another’s judgment.') ]});
  D('deferential',{etymology:E('deferential is formed from deference plus -ial; it describes behavior that shows respectful regard or readiness to yield to another person.','deferential'),contexts:[C('deferential.s1','职场交流','The new analyst was deferential toward the experienced auditor, listening carefully before offering a different interpretation.','新分析师对经验丰富的审计员十分恭敬，认真听完后才提出不同解释。','The new analyst was deferential toward the experienced auditor / listening carefully / before offering a different interpretation.','deferential toward + 人表示对其表现尊重；不同意见仍可礼貌提出。','先认真倾听资深同事，体现尊重义 s1。'),C('deferential.s2','协商语气','Her deferential reply accepted the chair’s preferred schedule without insisting on her own choice.','她顺从的答复接受了主席偏好的时间安排，没有坚持自己的选择。','Her deferential reply accepted the chair’s preferred schedule / without insisting on her own choice.','deferential 描述愿意让步、顺从他人意愿。','接受对方的安排且不坚持己见，符合 s2。')],mistakes:[M('The deferential assistant mocked the director, ignored the request, and insisted that only her own wishes mattered.','The defiant assistant mocked the director, ignored the request, and insisted that only her own wishes mattered.','嘲弄并拒绝让步表现为反抗，不是恭敬顺从。','confusable')],quiz:[Q('deferential',1,1,'A deferential response to a senior colleague is?',['respectful','insulting','unrelated to the conversation'],'respectful','Deferential describes polite respect toward someone regarded as senior.'),Q('deferential',2,2,'A person who willingly yields to another’s preference is?',['deferential','defiant','defective'],'deferential','The word can describe readiness to give way.'),Q('deferential',3,1,'Which behavior is most deferential?',['asking a judge a question in a respectful tone','shouting over the judge and refusing all rulings','leaving without listening'],'asking a judge a question in a respectful tone','Respectful conduct toward an authority is deferential.'),Q('deferential',4,2,'“He was deferential to the host’s wishes” means he?',['readily accepted the host’s preferences','publicly condemned the host','damaged the host’s property'],'readily accepted the host’s preferences','This sentence uses the yielding or compliant sense.') ]});
  D('defiance',{etymology:E('defiance comes through Old French defier, from Latin disfidare “renounce faith or loyalty”; it names bold refusal to obey or accept a threat.','defiance'),contexts:[C('defiance.s1','校园规则','The students’ peaceful defiance of the unfair rule drew attention to its unequal treatment of different families.','学生们和平违抗不公平规定，引起了人们对该规则差别对待不同家庭的关注。','The students’ peaceful defiance of the unfair rule / drew attention / to its unequal treatment of different families.','defiance of + 规则表示公然拒绝服从；peaceful 描述行动方式。','学生公开不服从规定，体现违抗义。')],mistakes:[M('The driver showed defiance by following every instruction immediately and never challenging the order.','The driver showed obedience by following every instruction immediately and never challenging the order.','毫无异议地服从命令体现 obedience，不是 defiance。')],quiz:[Q('defiance',1,1,'A bold refusal to obey an unfair order is?',['defiance','deference','dedication'],'defiance','Defiance is open refusal to obey a person or rule.'),Q('defiance',2,1,'A sign of defiance toward a threat is?',['continuing the protest despite the threat','quietly withdrawing at once','thanking the threatener for the warning'],'continuing the protest despite the threat','Defiance can show that someone will not yield to a threat.'),Q('defiance',3,1,'Which noun is the opposite of defiance?',['obedience','resistance','disobedience'],'obedience','Obedience means complying rather than openly refusing.'),Q('defiance',4,1,'A public act of defiance communicates?',['a refusal to submit','a respectful acceptance','a careful deduction'],'a refusal to submit','The noun emphasizes bold noncompliance.') ]});
  D('defiant',{etymology:E('defiant is formed from defy plus -ant, through French défier and Latin disfidare “renounce faith”; it describes open resistance or a challenging attitude.','defiant'),contexts:[C('defiant.s1','劳资纠纷','The workers remained defiant and refused to return until the company withdrew the unsafe schedule.','工人们仍然坚决反抗，拒绝复工，直到公司撤回不安全的排班方案。','The workers remained defiant / and refused to return / until the company withdrew the unsafe schedule.','defiant 作表语形容词，refused to return 说明公开拒绝服从。','工人公开抗命并坚持要求改变，符合 s1。'),C('defiant.s2','公开抗议','She gave the guards a defiant look and continued speaking despite their warning.','她挑衅地看了警卫一眼，尽管对方警告仍继续发言。','She gave the guards a defiant look / and continued speaking / despite their warning.','defiant 修饰 look，体现不怕对抗的态度。','面对警告仍继续发言并显露无惧，符合 s2。')],mistakes:[M('The defiant witness eagerly obeyed every demand and showed no resistance to the order.','The compliant witness eagerly obeyed every demand and showed no resistance to the order.','毫无抵抗地服从命令体现顺从，不是 defiant。')],quiz:[Q('defiant',1,1,'Workers who openly refuse an order are?',['defiant','deferential','dedicated'],'defiant','Defiant means openly refusing to obey.'),Q('defiant',2,2,'A defiant glance suggests the person?',['is unafraid to oppose someone','is eager to yield','is measuring a slope'],'is unafraid to oppose someone','This sense conveys a challenging, unafraid attitude.'),Q('defiant',3,1,'Which response sounds defiant?',['“I will not follow that unjust order.”','“I accept every instruction without question.”','“I do not know what the order says.”'],'“I will not follow that unjust order.”','The speaker openly refuses to obey.'),Q('defiant',4,2,'The adjective defiant is closest to?',['challenging and resistant','respectful and yielding','faulty and malfunctioning'],'challenging and resistant','A defiant person openly resists authority or opposition.') ]});
  D('deficiency',{etymology:E('deficiency comes from deficient plus -cy; deficient is from Latin deficere “fail or be lacking.” The noun means either a lack of something needed or a flaw.','deficiency'),contexts:[C('deficiency.s1','营养健康','Blood tests revealed an iron deficiency, so the doctor recommended dietary changes and a follow-up test.','血液检查显示缺铁，因此医生建议调整饮食并复查。','Blood tests revealed an iron deficiency / so the doctor recommended dietary changes / and a follow-up test.','deficiency of/in + 物质表示缺乏；iron deficiency 是常用搭配。','体内缺少必需铁元素，符合 s1。'),C('deficiency.s2','设备评估','The inspection found a serious deficiency in the alarm system: it did not sound when smoke reached the upper floor.','检查发现警报系统有严重缺陷：烟雾到达楼上时它没有响。','The inspection found a serious deficiency in the alarm system / it did not sound / when smoke reached the upper floor.','deficiency in + 系统表示其功能缺陷。','警报器未按需启动，是系统本身的缺陷义。')],mistakes:[M('The patient had an iron deficiency even though tests showed normal levels and the diet supplied more than enough iron.','The patient had adequate iron levels because tests were normal and the diet supplied enough iron.','指标正常且摄入充足，不支持铁元素缺乏。')],quiz:[Q('deficiency',1,1,'A shortage of iron in the body is an iron?',['deficiency','defiance','dedication'],'deficiency','Deficiency means a lack of something needed.'),Q('deficiency',2,2,'A fire alarm that fails to sound has a?',['deficiency','deduction','deference'],'deficiency','The noun can also mean a fault in a system.'),Q('deficiency',3,1,'Which condition is a deficiency?',['too little vitamin D for normal health','an adequate supply of clean water','a surplus of required minerals'],'too little vitamin D for normal health','A deficiency is a shortfall of a necessary substance.'),Q('deficiency',4,2,'An engineering report notes a deficiency in a safety barrier. It identifies?',['a flaw in the barrier','the barrier’s paint colour only','a person who supports the barrier'],'a flaw in the barrier','The second sense is a fault in something.') ]});
  D('defile',{etymology:E('defile as a verb comes through Middle English and French forms for fouling or trampling; the noun for a narrow mountain pass comes from French défilé, a constricted passage.','defile'),contexts:[C('defile.s1','文物保护','Visitors were warned not to defile the ancient shrine by carving their initials into its painted wooden doors.','游客被提醒不要在古老神龛的彩绘木门上刻名字，以免玷污它。','Visitors were warned / not to defile the ancient shrine / by carving their initials / into its painted wooden doors.','defile + 物体表示弄脏或玷污；by 说明造成损害的方式。','刻划会损坏并玷污神龛，符合 s1。'),C('defile.s2','山地地理','The army moved through a narrow defile between two cliffs, where the path allowed only a single line of pack animals.','军队穿过两座峭壁间狭窄的山隘，那里仅容一列驮畜通过。','The army moved through a narrow defile between two cliffs / where the path allowed only a single line of pack animals.','defile 作名词指山间狭窄通道；where 从句说明其狭窄特征。','两侧峭壁间仅容单列通行，体现 s2。')],mistakes:[M('The hikers called the broad open valley a defile because it had no narrow passage or enclosing cliffs.','The hikers called the narrow passage between the cliffs a defile.','开阔山谷没有狭窄通道特征，不能称为 defile 的地理义。')],quiz:[Q('defile',1,1,'Carving initials into a monument would?',['defile it','deepen it','decode it'],'defile it','The verb means to make a place or object dirty or no longer pure.'),Q('defile',2,2,'A narrow passage between mountain cliffs is a?',['defile','delta','decor'],'defile','As a noun, defile can mean a narrow mountain pass.'),Q('defile',3,1,'Which action would defile a protected shrine?',['smearing paint across its altar','installing a protective cover','cleaning dust under supervision'],'smearing paint across its altar','The paint spoils or contaminates the shrine.'),Q('defile',4,2,'A column of animals can pass only one at a time through a mountain gap. The gap is a?',['defile','freeway','plateau'],'defile','A confined mountain passage is a defile.') ]});
  D('definition',{etymology:E('definition comes from Latin definitio, from definire “set limits or define”; the noun can mean a word explanation or the clarity of an image or sound.','definition'),contexts:[C('definition.s1','词典使用','The dictionary gives a concise definition of “harvest” and then provides two examples of the word in context.','词典先给出“harvest”的简明定义，然后提供两个语境例句。','The dictionary gives a concise definition of “harvest” / and then provides two examples / of the word in context.','definition of + 词语表示词义解释。','词典说明一个词表示什么，符合 s1。'),C('definition.s2','显示设备','The monitor has excellent definition, so fine lines in the map remain distinct even when the image is enlarged.','这台显示器的清晰度很高，因此地图放大后细线仍然清楚可辨。','The monitor has excellent definition / so fine lines in the map remain distinct / even when the image is enlarged.','image definition 指图像细节清晰度。','放大后细线依旧清楚体现图像清晰度义。')],mistakes:[M('The dictionary definition was useless because it explained what the word meant in clear terms and included an example.','The dictionary definition was useful because it clearly explained the word and included an example.','清楚说明词义并提供例子正是 definition 的作用。')],quiz:[Q('definition',1,1,'A dictionary entry that explains a word provides its?',['definition','defiance','deformation'],'definition','A definition explains what a word means.'),Q('definition',2,2,'A screen with sharp fine details has high?',['definition','defection','deference'],'definition','Definition can mean the clarity of an image or sound.'),Q('definition',3,1,'Which is the clearest example of a definition?',['“A peninsula is land nearly surrounded by water.”','“I like this word.”','“The page is blue.”'],'“A peninsula is land nearly surrounded by water.”','The sentence explains the meaning of a term.'),Q('definition',4,2,'If a recording has poor definition, it likely sounds?',['unclear or lacking detail','perfectly sharp','unusually deferential'],'unclear or lacking detail','The audio sense concerns clarity and detail.') ]});
  D('definitive',{etymology:E('definitive comes through French from Latin definitivus, from definire “set limits”; it can mean final and authoritative, and in grammar a definitive determiner limits a noun reference.','definitive'),contexts:[C('definitive.s1','医学指南','The specialist’s definitive review combined the test results and clinical history to establish the final diagnosis.','专科医生的权威性审查综合了检测结果和病史，确定了最终诊断。','The specialist’s definitive review combined the test results and clinical history / to establish the final diagnosis.','definitive 修饰 review，表示权威、完整且定论性的。','综合证据后给出最终诊断，体现 s1。'),C('definitive.s2','语法课堂','In “this book,” the word this is a definitive determiner because it identifies which book the speaker means.','在“this book”中，this 是限定词，因为它指出说话者指的是哪一本书。','In “this book,” the word this is a definitive determiner / because it identifies which book the speaker means.','this 限定名词 book 的指称范围，体现语法义。','限定词 this 明确指向哪一本书，符合 s2。')],mistakes:[M('The definitive report was described as final, tentative, incomplete, and certain to be replaced tomorrow.','The preliminary report was described as tentative and likely to be replaced tomorrow.','暂定且很快会替换的报告不具 definitive 所指的最终权威性。')],quiz:[Q('definitive',1,1,'A definitive guide is?',['complete and authoritative','temporary and uncertain','decorative but unreadable'],'complete and authoritative','Definitive describes a final, authoritative treatment.'),Q('definitive',2,2,'In grammar, “this” in “this book” is a?',['definitive determiner','past-tense verb','sound unit'],'definitive determiner','It limits the noun by identifying a particular book.'),Q('definitive',3,1,'Which finding is most likely definitive?',['a final result accepted as authoritative','an early guess pending new tests','a question with no evidence'],'a final result accepted as authoritative','Definitive means settled and authoritative.'),Q('definitive',4,2,'A definitive article or determiner helps?',['limit which noun or referent is meant','show how loud a sound is','describe seasonal leaf loss'],'limit which noun or referent is meant','The grammar sense is a word such as the or this that narrows reference.') ]});
  D('definitively',{etymology:E('definitively is formed from definitive plus the adverb suffix -ly; it means in a final, authoritative way that settles a question.','definitively'),contexts:[C('definitively.s1','科学证据','The second independent test definitively ruled out contamination, allowing the laboratory to release the batch.','第二次独立检测最终排除了污染的可能，使实验室能够放行这批产品。','The second independent test definitively ruled out contamination / allowing the laboratory / to release the batch.','definitively 修饰 ruled out，强调结论已明确且有权威依据。','独立复检给出定论并据此放行，符合最终确定义。')],mistakes:[M('The preliminary scan definitively proved the diagnosis even though the result was uncertain and further tests were still required.','The preliminary scan tentatively suggested the diagnosis, while further tests were still required.','不确定且需要复检的初步结果不是最终权威结论。')],quiz:[Q('definitively',1,1,'A second test settles the question with certainty. It answers it?',['definitively','deferentially','decoratively'],'definitively','The adverb means in a final and authoritative way.'),Q('definitively',2,1,'Which sentence uses definitively naturally?',['The lab definitively ruled out the contaminant after repeated tests.','The lab definitively maybe found something, but no result exists.','The lab measured the sample definitively in litres of sound.'],'The lab definitively ruled out the contaminant after repeated tests.','Repeated evidence supports a settled conclusion.'),Q('definitively',3,1,'A question answered definitively is answered?',['conclusively','uncertainly','temporarily'],'conclusively','Definitively means giving a final answer.'),Q('definitively',4,1,'The court definitively established the date. The date is now?',['settled by an authoritative decision','only a guess','less clear than before'],'settled by an authoritative decision','The adverb signals an authoritative resolution.') ]});
  D('deflate',{etymology:E('deflate is formed from de- and inflate, ultimately related to Latin flare “to blow”; it can mean release air, reduce economic activity, or lessen confidence.','deflate'),contexts:[C('deflate.s1','自行车维修','Before packing the bicycle, Omar deflated the spare tyre slightly so it would fit inside the repair bag.','打包自行车前，奥马尔稍微给备用轮胎放了些气，让它能装进维修包。','Before packing the bicycle / Omar deflated the spare tyre slightly / so it would fit inside the repair bag.','deflate + tyre 表示放气；so 引出放气目的。','从轮胎放出部分空气使其缩小，符合 s1。'),C('deflate.s2','情绪反应','The harsh score deflated the novice pianist, but her teacher encouraged her to keep practicing.','严厉的评分让这位初学钢琴者泄了气，但老师鼓励她继续练习。','The harsh score deflated the novice pianist / but her teacher encouraged her / to keep practicing.','deflate 作及物动词表示打击信心；but 体现情绪转折。','评分使她信心下降，对应 s2。')],mistakes:[M('The mechanic deflated the tyre by pumping in more air until it became completely firm.','The mechanic inflated the tyre by pumping in more air until it became completely firm.','加气使轮胎鼓起是 inflate；deflate 是放气。','confusable')],quiz:[Q('deflate',1,1,'To make an inflated balloon smaller, you?',['deflate it','defer it','defame it'],'deflate it','Deflate means to release air from an inflated object.'),Q('deflate',2,2,'A disappointing result can deflate someone by?',['reducing their confidence','making their shoes larger','increasing air pressure in a tyre'],'reducing their confidence','The figurative sense is to make a person less confident.'),Q('deflate',3,1,'Which action would deflate a football?',['letting air escape through its valve','pumping additional air into it','painting its outer surface'],'letting air escape through its valve','Releasing air makes the ball smaller and softer.'),Q('deflate',4,2,'In economic reporting, deflate prices or activity means?',['reduce them','make them expand rapidly','translate them into a code'],'reduce them','The verb can also refer to reducing prices or economic activity.') ]});
  D('deflation',{etymology:E('deflation is formed from deflate plus -ion; in economics it means a general fall in prices, while physically it is the release of air or gas.','deflation'),contexts:[C('deflation.s1','宏观经济','The central bank studied persistent deflation as average prices fell and businesses delayed investment amid weakening demand.','平均物价下跌、需求减弱且企业推迟投资，央行因此研究持续通货紧缩。','The central bank studied persistent deflation / as average prices fell / and businesses delayed investment / amid weakening demand.','deflation 指总体价格水平下降；as 引出经济现象。','平均物价持续下落并伴随经济活动减弱，符合 s1。'),C('deflation.s2','球具维修','The slow deflation of the basketball became obvious as it softened overnight despite a tightly closed valve.','篮球即使气阀拧紧，过夜后仍变软，慢慢漏气的情况很明显。','The slow deflation of the basketball became obvious / as it softened overnight / despite a tightly closed valve.','deflation of + 充气物体表示空气逐渐逸出。','球体失去空气后变软，对应物理义 s2。')],mistakes:[M('The country experienced deflation as prices rose steadily across the economy for several consecutive years.','The country experienced inflation as prices rose steadily across the economy for several consecutive years.','总体物价持续上涨是 inflation，不是 deflation。','confusable')],quiz:[Q('deflation',1,1,'A sustained general fall in prices is?',['deflation','inflation','dedication'],'deflation','In economics, deflation is a fall in the general price level.'),Q('deflation',2,2,'A slowly softening football may be undergoing?',['deflation','decolonization','degradation of its rank'],'deflation','Physically, deflation is the release of air or gas.'),Q('deflation',3,1,'Which trend signals deflation rather than inflation?',['average prices decline over time','average prices rise over time','prices stay constant while wages rise'],'average prices decline over time','Falling prices characterize deflation.'),Q('deflation',4,2,'A balloon shrinks as gas escapes. This is?',['deflation','deference','deformation of a reputation'],'deflation','The physical sense is loss of air or gas that makes an object smaller.') ]});
  D('deflect',{etymology:E('deflect comes from Latin deflectere, from de- plus flectere “bend”; it means to turn a moving object aside or redirect attention and criticism.','deflect'),contexts:[C('deflect.s1','工程防护','A steel plate deflected the flying fragments away from the control panel during the test.','测试中，钢板把飞来的碎片挡偏，使其没有撞到控制面板。','A steel plate deflected the flying fragments / away from the control panel / during the test.','deflect + 移动物体表示使其改变方向；away from 标记偏转方向。','钢板令碎片改变轨迹，符合 s1。'),C('deflect.s2','媒体采访','Asked about the missing funds, the director tried to deflect attention by discussing an unrelated expansion project.','被问及资金去向时，主管试图转移注意力，转而谈论无关的扩建项目。','Asked about the missing funds / the director tried to deflect attention / by discussing an unrelated expansion project.','deflect attention 表示把关注点从原问题引开。','主管避谈资金问题并转谈别事，符合 s2。')],mistakes:[M('The shield deflected the ball by keeping it on the exact same path toward the goalkeeper.','The shield deflected the ball away from its original path and past the goalkeeper.','保持球原路径不变不叫偏转；deflect 要令其改变方向。')],quiz:[Q('deflect',1,1,'A shield makes an incoming ball change direction. It?',['deflects the ball','deflates the ball','dedicates the ball'],'deflects the ball','Deflect means to make a moving object change direction.'),Q('deflect',2,2,'A spokesperson changes the subject to avoid a question. The spokesperson tries to?',['deflect attention','deforest the audience','degas the microphone'],'deflect attention','The figurative sense is to turn attention or criticism away.'),Q('deflect',3,1,'Which object can deflect a stream of water?',['an angled barrier','a flat open field far away','a quiet book inscription'],'an angled barrier','A barrier can redirect the moving stream.'),Q('deflect',4,2,'A politician deflects criticism by blaming an unrelated issue. The politician?',['redirects attention away from the criticism','answers the criticism directly','increases its sound level'],'redirects attention away from the criticism','This is the figurative sense of shifting attention.') ]});
  D('deforest',{etymology:E('deforest is formed from de- plus forest; the verb means to remove trees from an area, and in its stronger use to cut them faster than they regrow.','deforest'),contexts:[C('deforest.s1','土地开发','The project will deforest a strip of hillside to make room for a new road, removing most of the existing woodland.','这项工程将清除一条山坡地带的森林，为新公路腾出空间。','The project will deforest a strip of hillside / to make room for a new road / removing most of the existing woodland.','deforest + 地区表示清除其森林；to 引出清林的目的。','大面积移除林木以建设道路，符合 s1。'),C('deforest.s2','可持续管理','If the logging company continues to deforest the watershed faster than seedlings can grow, erosion will increase.','如果伐木公司继续以超过幼树生长的速度砍伐流域森林，侵蚀就会加剧。','If the logging company continues to deforest the watershed / faster than seedlings can grow / erosion will increase.','faster than 从句突出过度砍伐速度。','砍伐快于再生，体现滥伐义 s2。')],mistakes:[M('The logging firm deforested the hillside by planting native trees across every cleared slope.','The logging firm reforested the hillside by planting native trees across every cleared slope.','重新种树恢复森林是 reforest，不是清除森林的 deforest。','confusable')],quiz:[Q('deforest',1,1,'To deforest a tract of land is to?',['remove its forest','plant a new forest there','measure its slope'],'remove its forest','Deforest means to clear forest from an area.'),Q('deforest',2,2,'Cutting trees faster than they can grow back is to?',['deforest the area','decompress the area','defer the area'],'deforest the area','This use emphasizes excessive clearing beyond regrowth.'),Q('deforest',3,1,'Which action would deforest a hillside?',['clearing its trees for construction','protecting its woodland from logging','planting seedlings on bare land'],'clearing its trees for construction','Removing the trees is deforestation.'),Q('deforest',4,2,'A company rapidly cuts a forest without allowing regrowth. It?',['deforests the land','defends the land','dedicates the land'],'deforests the land','The verb can stress cutting faster than trees can regrow.') ]});
  D('deforestation',{etymology:E('deforestation is formed from deforest plus -ation; it names the clearing of forest trees and the process by which forest land becomes open ground.','deforestation'),contexts:[C('deforestation.s1','土地利用','Satellite images showed deforestation along the river, where large areas of trees had been cleared for cattle pasture.','卫星图像显示河边发生了森林砍伐，大面积树木被清除以开辟牧场。','Satellite images showed deforestation along the river / where large areas of trees / had been cleared for cattle pasture.','deforestation 指大面积清除树木；where 从句说明地点和原因。','树木被清除以改作牧场，符合 s1。'),C('deforestation.s2','环境变化','The long process of deforestation turned once-forested slopes into exposed ground vulnerable to erosion.','森林消失的长期过程把曾经有林的山坡变成容易受侵蚀的裸地。','The long process of deforestation / turned once-forested slopes into exposed ground / vulnerable to erosion.','process of deforestation 强调林地逐步变成裸地的过程。','林地转为裸地是 s2 所述变化过程。')],mistakes:[M('The report called it deforestation when seedlings gradually restored a forest on previously bare land.','The report called it reforestation when seedlings gradually restored a forest on previously bare land.','树木恢复、重新造林是 reforestation，与砍伐森林方向相反。','confusable')],quiz:[Q('deforestation',1,1,'Large-scale clearing of trees from a forest is?',['deforestation','deformation','deflation'],'deforestation','The word means clearing trees from a large area.'),Q('deforestation',2,2,'Forest land gradually becoming open ground is the process of?',['deforestation','deference','decomposition'],'deforestation','The process sense focuses on forest land changing into open ground.'),Q('deforestation',3,1,'Which land-use change is deforestation?',['woodland is cleared for pasture','pasture is planted with native trees','a forest is placed under protection'],'woodland is cleared for pasture','Clearing forest for another use is deforestation.'),Q('deforestation',4,2,'Deforestation can leave hillsides vulnerable to?',['erosion after tree cover is lost','improved forest cover','a rise in decibel level'],'erosion after tree cover is lost','The process removes the trees that protect the soil.') ]});
  D('deformation',{etymology:E('deformation comes from deform plus -ation; deform is from Latin deformare, “mis-shape.” The noun denotes a change that spoils an object’s normal shape.','deformation'),contexts:[C('deformation.s1','材料测试','The engineer measured permanent deformation in the metal beam after the load was removed and the beam failed to return to its original shape.','载荷移除后，金属梁仍未恢复原形，工程师因此测量了它的永久变形。','The engineer measured permanent deformation in the metal beam / after the load was removed / and the beam failed to return to its original shape.','deformation in + 材料表示形状改变；permanent 表示不可恢复。','梁卸载后仍弯曲，体现形状变形义。')],mistakes:[M('The plastic showed deformation after heating because it kept its exact original shape without bending or stretching.','The plastic showed no deformation after heating because it kept its exact original shape.','形状完全不变就没有 deformation。')],quiz:[Q('deformation',1,1,'A beam bends and stays bent after a load is removed. It has undergone?',['deformation','deference','decolonization'],'deformation','Deformation is a change that alters an object’s normal shape.'),Q('deformation',2,1,'Which event most clearly causes deformation?',['a metal panel warps under heat','a straight panel remains unchanged','a panel is measured without being touched'],'a metal panel warps under heat','Warping changes the panel’s original shape.'),Q('deformation',3,1,'In geology, pressure can cause rock?',['deformation','dedication','deflation'],'deformation','The noun applies to changes in the shape of rock as well as objects.'),Q('deformation',4,1,'A structure that returns to its original shape has not suffered permanent?',['deformation','defection','defiance'],'deformation','Permanent deformation remains after the force is removed.') ]});
  D('deformed',{etymology:E('deformed is the past participle and adjective of deform, from Latin deformare “to alter the shape”; it describes something twisted or misshapen.','deformed'),contexts:[C('deformed.s1','材料检查','The technician rejected the deformed metal bracket because its bent edges no longer aligned with the mounting holes.','技术员拒收了变形的金属支架，因为弯曲的边缘已无法对准安装孔。','The technician rejected the deformed metal bracket / because its bent edges / no longer aligned with the mounting holes.','deformed 作前置定语，描述支架形状已扭曲。','孔位错开说明支架失去正常形状，符合 s1。')],mistakes:[M('The deformed bracket fit perfectly because it was straight, symmetrical, and unchanged from its manufactured shape.','The undamaged bracket fit perfectly because it was straight, symmetrical, and unchanged from its manufactured shape.','保持原形且对称的支架并未变形。')],quiz:[Q('deformed',1,1,'A deformed bracket has?',['a shape that is twisted or misshapen','a flawless original shape','a sound measured in decibels'],'a shape that is twisted or misshapen','Deformed means the usual form has been altered.'),Q('deformed',2,1,'Which item is deformed?',['a wheel bent out of round','a wheel that passes inspection and remains circular','a wheel still inside its box'],'a wheel bent out of round','The bent wheel has lost its normal shape.'),Q('deformed',3,1,'A deformed pipe may be difficult to install because it?',['no longer has its intended shape','is made of a different colour','contains a written dedication'],'no longer has its intended shape','An altered shape can prevent proper fitting.'),Q('deformed',4,1,'Choose the closest meaning of deformed.',['misshapen','fully restored','carefully defended'],'misshapen','The adjective describes something twisted or out of shape.') ]});
  D('deformity',{etymology:E('deformity comes through French from Latin deformitas, from deformis “misshapen”; it names an abnormal shape of a body part or the condition of having one.','deformity'),contexts:[C('deformity.s1','医学影像','The scan showed a small deformity in the animal’s leg bone, and the veterinarian explained the available treatment options to its caretakers.','影像显示这只动物的腿骨有一处轻微畸形，兽医向照护者说明了可选的治疗方案。','The scan showed a small deformity in the animal’s leg bone / and the veterinarian explained / the available treatment options to its caretakers.','deformity 指形态异常的身体部位或该状况；医学语境保持中性。','影像检查发现骨骼形态异常，符合词义。')],mistakes:[M('The scan reported a deformity even though the bone had a normal shape and the radiologist found no abnormality.','The scan reported no deformity because the bone had a normal shape and no abnormality was found.','形态正常且没有异常发现，不支持 deformity 这一诊断。')],quiz:[Q('deformity',1,1,'A radiologist sees an abnormal shape in a bone. The finding may be a?',['deformity','deduction','deflation'],'deformity','Deformity names an abnormal shape or the condition.'),Q('deformity',2,1,'Which finding is closest to a deformity?',['a joint with an unusual structural shape','a healthy joint with normal structure','a joint measured in decibels'],'a joint with an unusual structural shape','The noun concerns an abnormal bodily shape.'),Q('deformity',3,1,'A medical report uses deformity to refer to?',['a structural abnormality','a respectful manner','a financial deduction'],'a structural abnormality','A deformity is an abnormal bodily shape or condition.'),Q('deformity',4,1,'Which phrase uses deformity in a neutral clinical context?',['an assessment of a congenital hand deformity','an insult directed at a patient','a description of a room’s decor'],'an assessment of a congenital hand deformity','The phrase identifies a medical condition without judging the person.') ]});
  D('defraud',{etymology:E('defraud comes from Latin defraudare, “to cheat or deprive by fraud,” from de- and fraus “deception”; it means deliberately cheating someone or an organization.','defraud'),contexts:[C('defraud.s1','金融调查','Investigators alleged that the broker used fake statements to defraud clients of their retirement savings.','调查人员指称，经纪人用虚假报表骗取客户的退休储蓄。','Investigators alleged / that the broker used fake statements / to defraud clients of their retirement savings.','defraud + 人 + of + 财物，是“骗取某人某物”的常见结构。','利用虚假报表骗走客户资金，符合 s1。'),C('defraud.s2','公益组织','The director was convicted of defrauding the charity by submitting invented expenses for work that was never done.','主管因提交虚构的工作费用、蓄意欺骗慈善机构而被定罪。','The director was convicted of defrauding the charity / by submitting invented expenses / for work that was never done.','defraud an organization 表示故意欺骗机构。','虚报费用以欺骗组织，符合 s2。')],mistakes:[M('The audit proved that the consultant defrauded the client by returning the full fee and accurately reporting every expense.','The audit proved that the consultant treated the client honestly by returning the full fee and reporting every expense.','退还费用并准确报告开支是诚实行为，与欺骗取财相反。')],quiz:[Q('defraud',1,1,'Taking clients’ savings through fake financial statements is to?',['defraud them','defrost them','defend them'],'defraud them','To defraud is to trick someone to obtain money or property.'),Q('defraud',2,2,'A worker invents expenses to cheat an organization. The worker?',['defrauds the organization','deflects the organization','defers the organization'],'defrauds the organization','The verb also means deliberately cheating a person or organization.'),Q('defraud',3,1,'Complete the common pattern: defraud a customer ___ money.',['of','at','by to'],'of','Defraud someone of something means cheat them out of it.'),Q('defraud',4,2,'Which behavior is defrauding a charity?',['submitting fake invoices to obtain its funds','donating money transparently','returning an accidental overpayment'],'submitting fake invoices to obtain its funds','The false invoices are a deliberate scheme to cheat the charity.') ]});
  D('defrost',{etymology:E('defrost is formed from de- plus frost; it means to remove ice or allow something frozen to thaw.','defrost'),contexts:[C('defrost.s1','厨房准备','Please defrost the frozen berries in the refrigerator overnight before adding them to the cake batter.','请把冷冻浆果放在冰箱里过夜解冻，然后再加入蛋糕面糊。','Please defrost the frozen berries / in the refrigerator overnight / before adding them to the cake batter.','defrost + frozen food 表示解冻；before 引出后续步骤。','浆果从冻结状态融化，符合 s1。')],mistakes:[M('The cook defrosted the berries by placing them in a freezer until they became even harder and more deeply frozen.','The cook froze the berries by placing them in a freezer until they became harder.','放进冷冻室使食物更冻是 freeze，不是 defrost。','confusable')],quiz:[Q('defrost',1,1,'To prepare frozen berries for use, you can?',['defrost them','deface them','defer them'],'defrost them','Defrost means to make frozen food thaw.'),Q('defrost',2,1,'An icy windshield is defrosted when?',['the ice is removed or melted','more frost is added','the glass is painted'],'the ice is removed or melted','Defrost also means to remove frost from a surface.'),Q('defrost',3,1,'Which action would defrost a freezer compartment?',['letting its built-up ice melt','adding another layer of ice','sealing the ice in a box'],'letting its built-up ice melt','Defrosting removes accumulated ice.'),Q('defrost',4,1,'Choose the natural use of defrost.',['Defrost the fish safely before cooking it.','Defrost the fish to make it freeze solid.','Defrost the recipe by reading it aloud.'],'Defrost the fish safely before cooking it.','The verb is appropriate for thawing frozen food.') ]});
  D('defunct',{etymology:E('defunct comes from Latin defunctus, the past participle of defungi “finish or perform”; it means no longer operating or existing, and as a noun is an old or formal term for a deceased person.','defunct'),contexts:[C('defunct.s1','机构档案','The archive preserves records from a defunct railway company that stopped operating more than fifty years ago.','档案馆保存着一家已停运五十多年的铁路公司的记录。','The archive preserves records / from a defunct railway company / that stopped operating more than fifty years ago.','defunct 修饰 company，表示机构已经停止运营。','公司早已停业，符合 s1。'),C('defunct.s2','历史文本','In the old legal record, the deceased owner was referred to as “the defunct,” a formal usage now uncommon in everyday speech.','在这份旧法律记录中，已故业主被称为“the defunct”；这种正式用法如今日常生活中已不常见。','In the old legal record / the deceased owner was referred to as “the defunct” / a formal usage / now uncommon in everyday speech.','defunct 作名词指死者，属于旧式或正式用法，现代更常用 deceased。','旧法律文书使用该名词指已故者，呼应罕见义 s2。')],mistakes:[M('The defunct newspaper still prints a new edition every morning and employs a full reporting staff.','The active newspaper still prints a new edition every morning and employs a full reporting staff.','仍每日出版并有完整员工的报纸仍在运营，不能称 defunct。')],quiz:[Q('defunct',1,1,'A company that stopped operating decades ago is?',['defunct','defiant','dedicated'],'defunct','Defunct means no longer operating or in existence.'),Q('defunct',2,2,'In older formal writing, “the defunct” may refer to?',['a person who has died','a living business owner','a narrow mountain pass'],'a person who has died','This noun sense is formal or old-fashioned.'),Q('defunct',3,1,'Which institution is defunct?',['a closed bank that no longer exists','a bank opening new branches','a bank processing transactions today'],'a closed bank that no longer exists','The institution is no longer operating.'),Q('defunct',4,2,'In current everyday English, which phrase is usually preferred for a person who has died?',['the deceased person','the defunct person in ordinary conversation','the deflated person'],'the deceased person','Defunct as a noun for a deceased person is now uncommon.') ]});
  D('degas',{etymology:E('degas is formed from de- plus gas; it means to remove gas dissolved in a liquid or trapped in a material or chamber.','degas'),contexts:[C('degas.s1','实验操作','The technician degassed the resin in a vacuum chamber so trapped bubbles would not weaken the finished component.','技术员在真空室中给树脂脱气，以免残留气泡削弱成品部件。','The technician degassed the resin in a vacuum chamber / so trapped bubbles / would not weaken the finished component.','degas + 材料作宾语；真空 chamber 用来移除残留气体。','去除树脂中的气泡和气体，符合 s1。')],mistakes:[M('The operator degassed the liquid by injecting more bubbles until it contained more dissolved air than before.','The operator aerated the liquid by injecting bubbles; to degas it, the operator would remove dissolved gas.','注入空气增加溶解气体是充气，与 degas 的除气相反。','confusable')],quiz:[Q('degas',1,1,'A laboratory removes trapped bubbles from resin. It?',['degasses the resin','defrosts the resin','defames the resin'],'degasses the resin','Degas means to take trapped or dissolved gas out of a material.'),Q('degas',2,1,'Why might a liquid be degassed before testing?',['to remove dissolved gas that could affect the result','to add more gas to it','to freeze it solid'],'to remove dissolved gas that could affect the result','Degassing removes gas from the sample.'),Q('degas',3,1,'A vacuum chamber is used to degas a sample by?',['drawing out trapped gas','adding a new paint layer','measuring its slope'],'drawing out trapped gas','Vacuum treatment can remove bubbles or dissolved gas.'),Q('degas',4,1,'Which verb is closest in meaning to degas?',['remove gas from','inflate with air','cool until frozen'],'remove gas from','The verb specifically means to take gas out.') ]});
  D('degenerative',{etymology:E('degenerative is formed from degenerate plus -ive; degenerate comes from Latin degenerare, “decline from one kind or standard.” The adjective describes gradual deterioration.','degenerative'),contexts:[C('degenerative.s1','神经医学','The neurologist explained that the degenerative condition could gradually affect movement, while treatment might help manage its symptoms.','神经科医生解释说，这种退化性疾病可能逐渐影响行动能力，但治疗或许能帮助控制症状。','The neurologist explained / that the degenerative condition could gradually affect movement / while treatment might help manage its symptoms.','degenerative 修饰 condition；gradually 表明症状逐步恶化。','病情会导致组织或能力逐渐衰退，符合 s1。')],mistakes:[M('The physician described the condition as degenerative because it restored damaged tissue and steadily improved the patient’s abilities.','The physician described the condition as regenerative because it restored damaged tissue and improved the patient’s abilities.','恢复组织和能力持续改善不符合 degenerative 所指的逐渐退化。','confusable')],quiz:[Q('degenerative',1,1,'A degenerative disease typically causes?',['gradual decline in tissue or ability','instant recovery of all damaged tissue','seasonal loss of tree leaves'],'gradual decline in tissue or ability','Degenerative describes a process that gradually worsens.'),Q('degenerative',2,1,'A condition that progressively damages joints is?',['degenerative','decorative','defensible'],'degenerative','Progressive tissue decline is the relevant meaning.'),Q('degenerative',3,1,'Which phrase uses degenerative accurately?',['a degenerative nerve disorder','a degenerative plan that improves each day','a degenerative unit of sound'],'a degenerative nerve disorder','The adjective commonly describes diseases causing gradual deterioration.'),Q('degenerative',4,1,'The word degenerative emphasizes that decline is?',['gradual and worsening','final and authoritative','a respectful response'],'gradual and worsening','A degenerative process progressively reduces function or condition.') ]});
  D('deglaciation',{etymology:E('deglaciation is formed from de- plus glaciation, from Latin glacies “ice”; it names the retreat or disappearance of glaciers and ice sheets.','deglaciation'),contexts:[C('deglaciation.s1','气候科学','Researchers reconstructed postglacial sea levels to estimate how quickly deglaciation proceeded after the last ice age.','研究人员重建冰后海平面变化，以估算上一次冰期结束后冰川消退的速度。','Researchers reconstructed postglacial sea levels / to estimate / how quickly deglaciation proceeded / after the last ice age.','deglaciation 指冰川融化并后退的过程；postglacial 提供时间背景。','冰期后冰川逐渐消融后退，符合 s1。'),C('deglaciation.s2','冰盖变化','The map shows deglaciation of the regional ice sheet, with exposed land appearing where permanent ice once covered the valley.','地图展示了区域冰盖消失后永久冰层覆盖过的山谷逐渐露出陆地。','The map shows deglaciation of the regional ice sheet / with exposed land appearing / where permanent ice once covered the valley.','deglaciation of + 冰盖表示大面积冰盖消融消失。','冰层消退、地面重新显露，符合 s2。')],mistakes:[M('The region experienced deglaciation as its glaciers advanced, thickened, and permanently covered more land.','The region experienced glaciation as its glaciers advanced and covered more land.','冰川推进扩张是 glaciation；deglaciation 指冰川消退。','confusable')],quiz:[Q('deglaciation',1,1,'The retreat and melting of glaciers is?',['deglaciation','deforestation','dedication'],'deglaciation','Deglaciation is the process of glaciers melting and retreating.'),Q('deglaciation',2,2,'A regional ice sheet disappears and exposes land. This is?',['deglaciation','deformation','deference'],'deglaciation','The word also refers to loss of a large ice sheet.'),Q('deglaciation',3,1,'Which evidence might indicate deglaciation?',['a glacier margin has retreated and uncovered bedrock','ice advances over a valley','a forest grows denser'],'a glacier margin has retreated and uncovered bedrock','Retreating ice exposes ground and indicates deglaciation.'),Q('deglaciation',4,2,'Deglaciation is the opposite of?',['glaciation, the growth or advance of glaciers','dehydration, loss of water','declassification of a record'],'glaciation, the growth or advance of glaciers','Deglaciation is ice retreat, whereas glaciation is glacier expansion.') ]});
  D('degradation',{etymology:E('degradation comes through French dégradation from Latin degradare, “reduce in rank or step down”; it can mean worsening quality or a lowering of rank or moral standing.','degradation'),contexts:[C('degradation.s1','环境监测','Soil degradation accelerated after vegetation was removed, leaving the hillside more vulnerable to erosion and drought.','植被移除后土壤退化加快，使山坡更容易受到侵蚀和干旱影响。','Soil degradation accelerated / after vegetation was removed / leaving the hillside more vulnerable / to erosion and drought.','degradation 指质量逐渐变差；after 说明恶化的诱因。','土壤质量变差且易受侵蚀，符合 s1。'),C('degradation.s2','职业处分','The officer viewed the public demotion as a degradation of rank and appealed the disciplinary decision.','这名军官认为公开降职是军衔的贬降，因此对纪律处分提出申诉。','The officer viewed the public demotion / as a degradation of rank / and appealed the disciplinary decision.','degradation of rank 表示地位或级别降低。','降职降低职位等级，符合 s2。')],mistakes:[M('The report described the restored wetland as environmental degradation even though its soil, water quality, and wildlife had all recovered.','The report described the restored wetland as environmental recovery because its soil, water quality, and wildlife had improved.','生态环境恢复改善，不是质量恶化。')],quiz:[Q('degradation',1,1,'A decline in soil quality is soil?',['degradation','deference','dedication'],'degradation','The noun describes a process of becoming worse in quality.'),Q('degradation',2,2,'A reduction in someone’s official rank can be called?',['degradation','deflation','deglaciation'],'degradation','The word also means lowering rank or standing.'),Q('degradation',3,1,'Which process shows environmental degradation?',['polluted soil becoming less able to support crops','a damaged wetland being fully restored','a forest gaining healthy tree cover'],'polluted soil becoming less able to support crops','The environment is worsening in quality.'),Q('degradation',4,2,'A demotion from captain to lieutenant is a?',['degradation in rank','defrosting process','book dedication'],'degradation in rank','A demotion lowers formal status.') ]});
  D('degrading',{etymology:E('degrading is the present participle and adjective of degrade, from Latin degradare “lower in rank”; as an adjective it describes treatment that humiliates or diminishes someone’s dignity.','degrading'),contexts:[C('degrading.s1','工作尊严','The employees called the unpaid public apology degrading because it required them to accept blame for a failure they had not caused.','员工们认为这场无偿的公开道歉有辱人格，因为它要求他们为并非自己造成的失误承担责任。','The employees called the unpaid public apology degrading / because it required them / to accept blame / for a failure they had not caused.','degrading 作宾语补足语形容词，评价做法使人感到受辱、失去尊严。','强迫员工为他人造成的问题公开认错，有损人格尊严。')],mistakes:[M('The degrading procedure treated every participant with respect, protected privacy, and allowed them to make their own choices.','The respectful procedure treated every participant with respect, protected privacy, and allowed them to make their own choices.','尊重隐私与自主选择体现尊重，不是羞辱或贬低人格。')],quiz:[Q('degrading',1,1,'A humiliating task that undermines a person’s dignity is?',['degrading','defensible','deciduous'],'degrading','Degrading describes treatment that makes someone feel ashamed or diminished.'),Q('degrading',2,1,'Which situation is most likely degrading?',['a supervisor publicly mocks an employee and strips away their dignity','a supervisor privately offers fair coaching','a team thanks a colleague for careful work'],'a supervisor publicly mocks an employee and strips away their dignity','Public humiliation is degrading treatment.'),Q('degrading',3,1,'A degrading comment is one that?',['insults or humiliates someone','gives accurate technical instructions','raises the clarity of an image'],'insults or humiliates someone','The adjective concerns loss of dignity or self-respect.'),Q('degrading',4,1,'Choose the closest opposite of degrading.',['respectful','humiliating','demeaning'],'respectful','Respectful treatment preserves a person’s dignity.') ]});
  D('dehydrated',{etymology:E('dehydrated is formed from dehydrate plus -ed; hydrate derives from Greek hydōr, “water.” It describes a body lacking water or food from which water has been removed.','dehydrated'),contexts:[C('dehydrated.s1','食品储存','The hikers packed dehydrated apple slices because the dried fruit weighed less and kept well in a sealed bag.','徒步者带了脱水苹果片，因为干果重量更轻，密封保存也不易变质。','The hikers packed dehydrated apple slices / because the dried fruit weighed less / and kept well in a sealed bag.','dehydrated 修饰食物，表示水分已被除去。','干果轻便且水分已去除，对应食品义 s1。')],mistakes:[M('The dehydrated fruit was dripping with water because all moisture had been added back to it.','The rehydrated fruit was dripping with water because moisture had been added back to it.','水分已除去的食品不应同时含有大量加回的水。','confusable')],quiz:[Q('dehydrated',1,1,'Dehydrated fruit has had what removed?',['most of its water','its magnetic field','its outer colour only'],'most of its water','Food can be called dehydrated after water is removed.'),Q('dehydrated',2,1,'Someone who has lost too much body water may be?',['dehydrated','defiant','deferential'],'dehydrated','The word also describes a body lacking water.'),Q('dehydrated',3,1,'Which item is most likely dehydrated?',['dried apricots made by removing water','fresh grapes washed and still juicy','a frozen block of ice'],'dried apricots made by removing water','Drying removes water from the fruit.'),Q('dehydrated',4,1,'A dehydrated sample is different from a rehydrated one because the first?',['has had water removed','has had water restored','contains only air'],'has had water removed','Rehydration adds water back; dehydration removes it.') ]});
  D('dehydration',{etymology:E('dehydration is formed from dehydrate plus -ion; dehydrate combines de- with hydrate, ultimately from Greek hydōr “water.” It names harmful body-water loss or the drying of material.','dehydration'),contexts:[C('dehydration.s1','野外安全','During the hot trek, the guide watched for signs of dehydration and scheduled water breaks in shaded places.','炎热徒步途中，向导留意脱水迹象，并安排大家在阴凉处休息饮水。','During the hot trek / the guide watched for signs of dehydration / and scheduled water breaks / in shaded places.','dehydration of the body 指水分流失；signs of 是常用搭配。','高温徒步时防范身体水分流失，体现健康义。')],mistakes:[M('The runner developed dehydration because she drank plenty of water and lost no fluid during the cool race.','The runner remained hydrated because she drank plenty of water and lost little fluid during the cool race.','充分补水且几乎没有流失水分，不能据此说发生脱水。')],quiz:[Q('dehydration',1,1,'A harmful loss of water from the body is?',['dehydration','deification','deforestation'],'dehydration','Dehydration names harmful body-water loss.'),Q('dehydration',2,1,'Drying a material by removing its water is also called?',['dehydration','defiance','deduction'],'dehydration','The noun also names the process of drying a substance.'),Q('dehydration',3,1,'Hot weather and inadequate fluid intake can raise the risk of?',['dehydration','defection','deformation'],'dehydration','The body may lose more water than it replaces.'),Q('dehydration',4,1,'Which statement uses dehydration in the body sense?',['The patient lost too much body water.','The sealed sample lost its magnetic field.','The forest gained more tree cover.'],'The patient lost too much body water.','The first statement describes bodily dehydration.') ]});
  D('deification',{etymology:E('deification comes from deify plus -ication; deify combines de- with Latin deus “god.” It means elevating a person, idea, or object to divine status.','deification'),contexts:[C('deification.s1','宗教史','The historian distinguished respectful remembrance from the deification of a ruler, in which followers treated the ruler as divine.','历史学家区分了尊敬地纪念统治者和将其神化：后者是追随者把统治者视为神。','The historian distinguished respectful remembrance / from the deification of a ruler / in which followers treated the ruler as divine.','deification of + 人/观念表示将其抬升到神的地位。','把统治者当作神明崇拜对应词义。')],mistakes:[M('The article called it deification because the crowd merely respected the leader as an ordinary elected official.','The article called it admiration because the crowd respected the leader as an ordinary elected official.','普通尊敬并未把人提升到神的地位，不构成 deification。')],quiz:[Q('deification',1,1,'Treating a human ruler as divine is?',['deification','dehydration','deletion'],'deification','Deification elevates a person to divine status.'),Q('deification',2,1,'Which action is closest to deification?',['worshipping an object as a god','remembering a teacher with respect','measuring a statue’s height'],'worshipping an object as a god','The object is given divine status.'),Q('deification',3,1,'The deification of an idea means the idea is?',['raised to a godlike or divine status','removed from a document','made easier to read'],'raised to a godlike or divine status','The noun can refer to elevating an idea as well as a person.'),Q('deification',4,1,'Respectful praise is not necessarily deification unless it?',['treats its subject as divine','mentions the subject by name','appears in a history book'],'treats its subject as divine','Ordinary admiration falls short of making something divine.') ]});
  D('deign',{etymology:E('deign came through Old French deignier from Latin dignari, “consider worthy”; it now often means agreeing, sometimes condescendingly, to do something one considers beneath oneself.','deign'),contexts:[C('deign.s1','人物描写','After several invitations, the celebrity finally deigned to speak with the local reporters, though her tone suggested she thought the meeting beneath her.','多次邀请之后，这位名人终于屈尊与当地记者交谈，但她的语气让人觉得她认为这场会面有失身份。','After several invitations / the celebrity finally deigned to speak with the local reporters / though her tone suggested / she thought the meeting beneath her.','deign 常接 to + 动词原形，带有居高临下地勉强答应之意。','名人认为会面低于自己的身份却终于答应，符合词义。')],mistakes:[M('The modest volunteer deigned to help because she considered helping neighbours an honour and never viewed it as beneath her.','The modest volunteer gladly agreed to help because she considered helping neighbours an honour.','乐于认为帮助邻居是荣幸，不体现 deign 中“屈尊做自认不值得做之事”的意味。')],quiz:[Q('deign',1,1,'A person who finally agrees to do a task they consider beneath them may?',['deign to do it','dehydrate it','deforest it'],'deign to do it','Deign often implies condescending agreement.'),Q('deign',2,1,'Which sentence best illustrates deign?',['The star deigned to answer one question after ignoring the reporters.','The star eagerly volunteered for every interview.','The star measured the sound in decibels.'],'The star deigned to answer one question after ignoring the reporters.','The reluctant, superior attitude fits the verb.'),Q('deign',3,1,'The verb deign is commonly followed by?',['to plus a base verb','a past participle only','a measurement in litres'],'to plus a base verb','The usual pattern is deign to do something.'),Q('deign',4,1,'If a manager does not deign to reply, the manager?',['refuses or considers replying beneath them','answers eagerly and warmly','cannot read the message'],'refuses or considers replying beneath them','Deign carries an implication of condescension or reluctance.') ]});
  D('dejected',{etymology:E('dejected is the past participle and adjective of deject, from Latin deicere “throw down”; it describes low spirits or a visibly sad, discouraged appearance.','dejected'),contexts:[C('dejected.s1','比赛结果','The dejected runner sat quietly after missing the qualifying time by less than a second.','这名沮丧的跑者在以不到一秒之差错过晋级成绩后，静静坐了下来。','The dejected runner sat quietly / after missing the qualifying time / by less than a second.','dejected 作表语形容词，说明失望后的心情。','差一点晋级却落选使跑者灰心，符合 s1。'),C('dejected.s2','情绪观察','With lowered eyes and drooping shoulders, the child looked dejected as the other students left for the trip.','其他学生出发旅行时，这个孩子垂着眼、耷拉着肩，看起来垂头丧气。','With lowered eyes and drooping shoulders / the child looked dejected / as the other students left for the trip.','look dejected 描述从神情、姿态看出悲伤。','低头和垂肩显示悲伤外在状态，对应 s2。')],mistakes:[M('The team looked dejected after its victory, cheering loudly and celebrating the win with smiles.','The team looked delighted after its victory, cheering loudly and celebrating the win with smiles.','欢呼庆祝胜利体现高兴，不是沮丧失望。','confusable')],quiz:[Q('dejected',1,1,'Someone who feels unhappy and has little hope is?',['dejected','delectable','defensive'],'dejected','Dejected means unhappy, disappointed, and discouraged.'),Q('dejected',2,2,'A person with lowered eyes and slumped shoulders may look?',['dejected','definitive','dehydrated'],'dejected','The word can describe a visibly sad posture or expression.'),Q('dejected',3,1,'Which event would most likely leave someone dejected?',['missing an important goal after months of effort','receiving the award they wanted','finishing a task exactly as hoped'],'missing an important goal after months of effort','A disappointing setback can cause low spirits.'),Q('dejected',4,2,'A dejected expression most likely shows?',['sadness or discouragement','confidence and excitement','anger at a rule only'],'sadness or discouragement','The visible sense concerns a sad, discouraged look.') ]});
  D('delectable',{etymology:E('delectable comes through French from Latin delectabilis, from delectare “delight”; it describes something very pleasant to taste or smell, or otherwise delightful.','delectable'),contexts:[C('delectable.s1','餐饮评论','The bakery served delectable almond pastries whose buttery smell reached the queue outside the shop.','这家面包店供应美味的杏仁点心，浓郁的黄油香飘到了店外的队伍里。','The bakery served delectable almond pastries / whose buttery smell / reached the queue outside the shop.','delectable 修饰食物，也可由香气体现其令人愉悦的感官效果。','点心美味且香气诱人，符合 s1。'),C('delectable.s2','旅行写作','The travel writer described the quiet garden as a delectable retreat from the noise of the crowded city.','旅行作家把这座安静花园描述成一处令人愉悦的去处，让人远离拥挤城市的喧闹。','The travel writer described the quiet garden / as a delectable retreat / from the noise of the crowded city.','delectable 可比喻形容非常吸引人、令人愉悦的事物。','花园作为迷人去处使人愉快，符合 s2。')],mistakes:[M('The delectable soup had a foul smell and an unpleasant taste that made every diner refuse a bite.','The unappetizing soup had a foul smell and an unpleasant taste that made every diner refuse a bite.','气味和味道都令人不快，不适合称为 delectable。')],quiz:[Q('delectable',1,1,'A pastry described as delectable is?',['extremely pleasant to taste','harmful to health','difficult to define'],'extremely pleasant to taste','Delectable often describes delicious food.'),Q('delectable',2,2,'A delightful garden may be called delectable because it is?',['very attractive and pleasing','no longer in existence','a coded message'],'very attractive and pleasing','The word also means very attractive or delightful.'),Q('delectable',3,1,'Which aroma is most likely delectable?',['fresh bread with a rich appetizing smell','spoiled food with a sour odor','a scentless empty room'],'fresh bread with a rich appetizing smell','The appealing aroma is extremely pleasant.'),Q('delectable',4,2,'The adjective delectable can describe?',['delicious food or an especially pleasing experience','only a broken machine','a person refusing to obey'],'delicious food or an especially pleasing experience','The word has both sensory and broader pleasurable uses.') ]});
  D('deleterious',{etymology:E('deleterious comes from Greek dēlētērios, “harmful or destructive,” through Latin and French; it describes an effect that causes harm, sometimes gradually.','deleterious'),contexts:[C('deleterious.s1','公共卫生','The report warned that prolonged exposure to the chemical could have deleterious effects on the workers’ health.','报告警告说，长期接触这种化学物质可能对工人健康造成有害影响。','The report warned / that prolonged exposure to the chemical / could have deleterious effects / on the workers’ health.','deleterious effects on + 对象是常见搭配。','持续接触可能损害健康，符合 s1。'),C('deleterious.s2','生态变化','Even a small daily leak had a deleterious impact on the marsh over several years, gradually reducing the number of nesting birds.','即使每天只有少量泄漏，几年下来也对沼泽造成了持续损害，筑巢鸟类逐渐减少。','Even a small daily leak had a deleterious impact on the marsh over several years / gradually reducing the number of nesting birds.','deleterious 描述随时间累积的损伤；over several years 表时间跨度。','长期污染逐渐损害湿地生态，符合 s2。')],mistakes:[M('The study found the treatment deleterious because it caused no harm and improved every measure of health.','The study found the treatment beneficial because it caused no harm and improved measures of health.','无害且改善健康是有益效果，不是 deleterious。','confusable')],quiz:[Q('deleterious',1,1,'A deleterious effect on health is?',['harmful','pleasant','final'],'harmful','Deleterious means causing harm.'),Q('deleterious',2,2,'Damage that builds up gradually over time can be described as?',['deleterious','delectable','definitive'],'deleterious','The word can describe ongoing damage rather than one sudden blow.'),Q('deleterious',3,1,'Which impact is deleterious?',['a pollutant slowly harming a wetland','a filter removing a pollutant','a clean stream supporting wildlife'],'a pollutant slowly harming a wetland','The pollutant causes damage to the ecosystem.'),Q('deleterious',4,2,'The phrase “deleterious to sleep” means?',['harmful to sleep','delightful during sleep','a final answer about sleep'],'harmful to sleep','The preposition to links the harmful effect with what is affected.') ]});
  D('deletion',{etymology:E('deletion comes from Latin deletio, from delere “wipe out or destroy”; it can mean the act of removing text or data and the part removed.','deletion'),contexts:[C('deletion.s1','文件管理','The editor restored the paragraph after an accidental deletion removed it from the shared document.','共享文档中的一段文字被意外删除后，编辑恢复了它。','The editor restored the paragraph / after an accidental deletion / removed it from the shared document.','deletion 作名词，表示删除动作或被删部分；accidental 修饰该事件。','段落从文档中消失后被恢复，体现删除义。')],mistakes:[M('The deletion kept every sentence in the file unchanged and added a new paragraph at the end.','The addition kept every sentence in the file unchanged and added a new paragraph at the end.','保留原文并添加段落是增加，不是删除。')],quiz:[Q('deletion',1,1,'Removing a paragraph from a document is a?',['deletion','deification','deflation'],'deletion','Deletion is the act of removing text or data.'),Q('deletion',2,1,'The deletion in a manuscript can refer to?',['the passage that was removed','the title added to the cover','the author’s dedication'],'the passage that was removed','The noun also refers to the part that has been deleted.'),Q('deletion',3,1,'Which action causes a deletion?',['erasing a file from a folder','copying the file to another folder','printing a second copy'],'erasing a file from a folder','Erasing removes the file from its former location.'),Q('deletion',4,1,'A genetic deletion involves?',['a segment of genetic material being lost','a new segment being copied twice','a protein changing its colour'],'a segment of genetic material being lost','Deletion can also name the loss of a sequence.') ]});
  D('delft',{etymology:E('delft as a common noun takes its name from the Dutch city of Delft, historically known for blue-and-white tin-glazed earthenware; it names pottery of that style.','delft'),contexts:[C('delft.s1','工艺品收藏','The museum displayed a delft plate with cobalt-blue flowers painted on its white glazed surface.','博物馆展出了一只代尔夫特陶盘，白色釉面上绘有钴蓝色花朵。','The museum displayed a delft plate / with cobalt-blue flowers / painted on its white glazed surface.','delft 作名词，指蓝白釉陶；小写作普通名词。','蓝色纹饰绘于白色釉陶表面，符合词义。')],mistakes:[M('The collector identified the plastic plate as delft even though it had no glaze and was made by injection moulding.','The collector identified the glazed blue-and-white earthenware plate as delft.','无釉塑料制品不是代尔夫特风格的釉陶。')],quiz:[Q('delft',1,1,'Delft pottery is traditionally associated with?',['blue-and-white glazed earthenware','unpainted paper','a magnetic instrument'],'blue-and-white glazed earthenware','Delft names pottery of the blue-and-white glazed kind.'),Q('delft',2,1,'The common noun delft takes its name from?',['a city in the Netherlands','a Greek letter','a Latin verb for running'],'a city in the Netherlands','Delft is the Dutch city associated with this pottery.'),Q('delft',3,1,'Which object is most likely delft?',['a white glazed plate decorated with blue painting','a plain plastic cup','a wooden spoon with no glaze'],'a white glazed plate decorated with blue painting','The blue-on-white glazed pottery matches the style.'),Q('delft',4,1,'A museum label reading delft most likely describes?',['a type of pottery','a formal debate','a loss of body water'],'a type of pottery','Delft is a pottery term.') ]});
  D('deliberately',{etymology:E('deliberately is formed from deliberate plus -ly; deliberate comes from Latin deliberare, “weigh carefully.” The adverb can mean intentionally or in a slow, careful manner.','deliberately'),contexts:[C('deliberately.s1','交通调查','The driver deliberately ignored the warning sign and entered the closed road despite seeing the barrier.','司机明明看到了路障，却故意无视警示牌驶入封闭道路。','The driver deliberately ignored the warning sign / and entered the closed road / despite seeing the barrier.','deliberately 修饰 ignored，说明行为是有意而非意外。','看见路障仍驶入，体现故意义 s1。'),C('deliberately.s2','实验操作','She deliberately turned the fragile sample with tweezers, moving slowly so its surface would not be scratched.','她小心从容地用镊子转动易碎样本，动作缓慢以免划伤表面。','She deliberately turned the fragile sample with tweezers / moving slowly / so its surface would not be scratched.','deliberately 可表示谨慎、缓慢地做某事。','慢慢小心操作对应 s2。')],mistakes:[M('The glass fell accidentally when a sudden gust knocked it off the table, but the report said she deliberately dropped it on purpose.','The glass fell accidentally when a sudden gust knocked it off the table.','突发阵风导致的意外不是有意行为，不能称 deliberately。')],quiz:[Q('deliberately',1,1,'Someone who knowingly ignores a clear warning acts?',['deliberately','accidentally','deferentially'],'deliberately','Here deliberately means on purpose.'),Q('deliberately',2,2,'To handle a fragile sample slowly and carefully is to move?',['deliberately','recklessly','defiantly'],'deliberately','The adverb can mean in a slow, careful way.'),Q('deliberately',3,1,'Which event was deliberate?',['She intentionally deleted the file after confirming the warning.','A power failure erased the file without anyone acting.','The file vanished for an unknown reason.'],'She intentionally deleted the file after confirming the warning.','Intentionally doing something is acting deliberately.'),Q('deliberately',4,2,'The speaker paused deliberately between words to make each one clear. The speaker paused?',['slowly and carefully','by accident','to deface the speech'],'slowly and carefully','This illustrates the careful, measured manner sense.') ]});
  D('deliberation',{etymology:E('deliberation comes from deliberate plus -ation, from Latin deliberare “weigh carefully”; it means extended careful thought or formal discussion before a decision.','deliberation'),contexts:[C('deliberation.s1','重要选择','After several hours of deliberation, the family chose the school that best matched the child’s learning needs.','经过数小时的仔细考虑，这家人选择了最符合孩子学习需求的学校。','After several hours of deliberation / the family chose the school / that best matched the child’s learning needs.','deliberation 指决定前认真权衡；after 引出考虑后的选择。','家庭比较需求数小时后作出决定，符合 s1。'),C('deliberation.s2','陪审程序','The jury began its deliberation after the judge summarized the evidence and sent the members to a private room.','法官总结证据并让陪审员进入私人房间后，陪审团开始审议。','The jury began its deliberation / after the judge summarized the evidence / and sent the members to a private room.','jury deliberation 是陪审团正式讨论并作决定。','陪审员集体讨论证据并准备裁决，符合 s2。')],mistakes:[M('The committee reached its decision without discussion or thought, yet the minutes described hours of deliberation.','The committee reached its decision without discussion or thought, so the minutes recorded that there was no deliberation.','没有讨论和思考就不可能发生数小时的审议。')],quiz:[Q('deliberation',1,1,'Carefully weighing options before choosing is?',['deliberation','deletion','deification'],'deliberation','The noun means long, careful thought before a decision.'),Q('deliberation',2,2,'A jury discusses evidence before reaching a verdict during?',['deliberation','deflation','dehydration'],'deliberation','Formal group discussion leading to a decision is deliberation.'),Q('deliberation',3,1,'Which situation involves deliberation?',['a family compares schools for several hours before deciding','a person picks the first option without thinking','a file is erased by mistake'],'a family compares schools for several hours before deciding','The family is considering choices carefully.'),Q('deliberation',4,2,'The committee’s deliberations are its?',['formal discussions aimed at a decision','decorative borders','measures of sound'],'formal discussions aimed at a decision','Group deliberation is discussion by people who must decide.') ]});
  D('delightful',{etymology:E('delightful is formed from delight plus -ful; delight came through Old French from Latin delectare “charm or please.” The adjective describes something highly pleasing or charming.','delightful'),contexts:[C('delightful.s1','休闲体验','The small concert was delightful, with clear acoustics, thoughtful musicians, and a relaxed audience.','这场小型音乐会令人愉快：音响清晰，乐手用心，观众也很放松。','The small concert was delightful / with clear acoustics / thoughtful musicians / and a relaxed audience.','delightful 作表语形容词，表示带来愉悦和快乐。','音乐会整体体验令人开心，符合 s1。'),C('delightful.s2','人物描写','Their delightful neighbour brought homemade soup and remembered every child’s name.','他们那位可爱的邻居送来亲手做的汤，还记得每个孩子的名字。','Their delightful neighbour brought homemade soup / and remembered every child’s name.','delightful 可形容迷人、讨人喜欢的人。','体贴友善的行为使邻居显得可爱亲切，对应 s2。')],mistakes:[M('The delightful visit left everyone miserable, bored, and eager to escape as soon as possible.','The unpleasant visit left everyone miserable, bored, and eager to escape as soon as possible.','全程痛苦无聊且人人想离开，不能说令人愉快。','confusable')],quiz:[Q('delightful',1,1,'An experience that gives great pleasure is?',['delightful','deleterious','defunct'],'delightful','Delightful means giving a lot of pleasure and happiness.'),Q('delightful',2,2,'A charming neighbour who is easy to like is?',['delightful','deformed','defiant'],'delightful','The adjective can mean charming and likable.'),Q('delightful',3,1,'Which afternoon sounds delightful?',['one with a peaceful garden concert and good company','one spent in a noisy room with a broken heater','one filled with harmful fumes'],'one with a peaceful garden concert and good company','The pleasant event would give a lot of enjoyment.'),Q('delightful',4,2,'“A delightful child” most likely describes a child who is?',['charming and pleasant to be around','no longer operating','difficult to define'],'charming and pleasant to be around','The second sense describes someone charming and likable.') ]});
  D('delineate',{etymology:E('delineate comes from Latin delineare, “mark out with lines,” from de- and linea “line”; it means to describe something clearly or draw its outline.','delineate'),contexts:[C('delineate.s1','项目规划','The contract delineates each contractor’s responsibilities so that no stage of the renovation is left unassigned.','合同清楚界定了每位承包商的职责，确保装修的每个阶段都有人负责。','The contract delineates each contractor’s responsibilities / so that no stage of the renovation / is left unassigned.','delineate responsibilities 表示明确描述或界定责任。','合同清楚说明各方职责，符合 s1。'),C('delineate.s2','地图绘制','The surveyor used a fine pencil to delineate the property boundary on the topographic map.','测量员用细铅笔在地形图上画出地界轮廓。','The surveyor used a fine pencil / to delineate the property boundary / on the topographic map.','delineate + boundary 表示画出或标明边界。','在地图上勾画地界，符合 s2。')],mistakes:[M('The contract failed to delineate any duties because it clearly listed every task and assigned each one to a named person.','The contract delineated the duties by listing every task and assigning each one to a named person.','清楚列出并分配职责正是 delineate，而非未能界定。')],quiz:[Q('delineate',1,1,'A contract that clearly explains each person’s duties?',['delineates the duties','deletes the duties','dehydrates the duties'],'delineates the duties','Delineate can mean describe or define clearly.'),Q('delineate',2,2,'A surveyor draws the outline of a boundary to?',['delineate it','deify it','deflate it'],'delineate it','The verb can mean to draw an outline.'),Q('delineate',3,1,'Which action best fits delineate a plan?',['set out its stages clearly','hide all its steps','measure its sound level'],'set out its stages clearly','The verb means describe something clearly and in detail.'),Q('delineate',4,2,'A mapmaker uses ink to delineate a coastline. The mapmaker?',['draws its outline','removes it from the map','turns it into a river delta'],'draws its outline','Delineating an outline means marking its shape with lines.') ]});
  D('delineation',{etymology:E('delineation comes from delineate plus -ion, from Latin delineare “mark out with lines”; it means a careful description or a marked outline or boundary.','delineation'),contexts:[C('delineation.s1','职责分工','The policy provides a clear delineation of the two agencies’ duties, including who responds first to each type of emergency.','该政策清楚界定了两个机构的职责，包括各类紧急情况由谁首先应对。','The policy provides a clear delineation of the two agencies’ duties / including who responds first / to each type of emergency.','delineation of duties 表示职责的明确划分。','政策说明职责边界及具体分工，符合 s1。')],mistakes:[M('The policy offered no delineation of responsibilities even though it clearly assigned every duty and named the responsible agency.','The policy offered a clear delineation of responsibilities by assigning every duty to a named agency.','职责已清楚分配并列明机构，说明存在明确界定。')],quiz:[Q('delineation',1,1,'A clear delineation of duties is?',['a careful description or division of responsibilities','a removal of every responsibility','an increase in sound'],'a careful description or division of responsibilities','Delineation names a careful description or marking of boundaries.'),Q('delineation',2,1,'On a map, the delineation of a border is?',['the line or outline marking it','the removal of the map','the map’s smell'],'the line or outline marking it','The word also refers to a marked boundary.'),Q('delineation',3,1,'Which document most needs delineation of roles?',['an emergency response plan shared by agencies','a blank sheet of paper','a list of unrelated colours'],'an emergency response plan shared by agencies','Clear role boundaries help define responsibility.'),Q('delineation',4,1,'A detailed delineation of a character gives?',['a clear description of the character','a sound measurement','a list of deleted files'],'a clear description of the character','Delineation can mean careful description.') ]});
  D('delinquency',{etymology:E('delinquency comes from Latin delinquentia, from delinquere “fail or commit an offense”; it can mean youth antisocial behavior or failure to meet an obligation such as a payment.','delinquency'),contexts:[C('delinquency.s1','青少年支持','The youth program addresses delinquency by offering mentoring, tutoring, and safe activities after school.','这个青少年项目通过提供导师辅导、课业帮助和课后安全活动来应对青少年违法行为。','The youth program addresses delinquency / by offering mentoring / tutoring / and safe activities after school.','delinquency 在此指青少年违法或反社会行为。','项目针对青少年不良行为并提供支持，符合 s1。'),C('delinquency.s2','账款管理','The lender sent a reminder after the account entered delinquency because the monthly payment had not arrived by its due date.','月付款到期未到账、账户进入拖欠状态后，贷款方发出了提醒。','The lender sent a reminder / after the account entered delinquency / because the monthly payment had not arrived by its due date.','payment delinquency 指未按期履行还款义务。','逾期未付款体现 s2。')],mistakes:[M('The account was in delinquency even though every payment arrived on time and no duty had been missed.','The account was in good standing because every payment arrived on time and no duty had been missed.','按时付款、没有违约不能称为 delinquency。')],quiz:[Q('delinquency',1,1,'Antisocial or criminal behavior by young people can be called?',['delinquency','deification','delineation'],'delinquency','The word often refers to juvenile offending or antisocial behavior.'),Q('delinquency',2,2,'A missed payment that remains overdue may put an account into?',['delinquency','delectability','deglaciation'],'delinquency','The word also means failure to meet an obligation, such as paying a debt.'),Q('delinquency',3,1,'A youth mentoring program may aim to reduce?',['juvenile delinquency','dehydration','image definition'],'juvenile delinquency','The program addresses unlawful or antisocial behavior among young people.'),Q('delinquency',4,2,'Payment delinquency means?',['a required payment is late or missed','a payment arrived early','a payment was made twice by mistake'],'a required payment is late or missed','Delinquency can mean failure to pay a debt when due.') ]});
  D('delinquent',{etymology:E('delinquent comes from Latin delinquens, present participle of delinquere “fail or commit an offense”; it can be a person who repeatedly breaks rules or an adjective for overdue payment or neglected duty.','delinquent'),contexts:[C('delinquent.s1','青少年司法','The community program pairs each young delinquent with a trained mentor and helps the teenager return to school.','社区项目为每位有违法行为的青少年安排一名受训导师，并帮助其重返学校。','The community program pairs each young delinquent with a trained mentor / and helps the teenager return to school.','delinquent 作名词指经常违法或违反社会规范的人；语境用支持性措辞。','项目对象是有违法行为的青少年，符合 s1。'),C('delinquent.s2','贷款提醒','The bank contacted the delinquent borrower after two scheduled payments were missed.','借款人错过两次约定还款后，银行联系了这位拖欠款项的借款人。','The bank contacted the delinquent borrower / after two scheduled payments were missed.','delinquent 修饰 borrower，表示未按时履行还款义务。','借款逾期未还，对应 s2。')],mistakes:[M('The account was delinquent because the borrower paid every installment in full before its due date.','The account was current because the borrower paid every installment before its due date.','每期按时足额还款的账户并未拖欠。')],quiz:[Q('delinquent',1,1,'A teenager repeatedly breaking the law may be called a young?',['delinquent','deferential','delectable'],'delinquent','The noun can refer to a person, especially a young one, who repeatedly breaks rules.'),Q('delinquent',2,2,'A delinquent payment is?',['overdue','paid early','cancelled before it is due'],'overdue','The adjective means failing to pay what is owed on time.'),Q('delinquent',3,1,'Which program might serve young delinquents?',['a mentoring and school re-entry program','a pottery exhibition','a weather station'],'a mentoring and school re-entry program','Support programs may work with young people who have broken rules.'),Q('delinquent',4,2,'A delinquent duty is one that has been?',['neglected or left undone','completed well ahead of schedule','clearly defined'],'neglected or left undone','The adjective can describe neglecting an obligation.') ]});
  D('delirium',{etymology:E('delirium comes from Latin delirium, from delirare “be out of one’s mind,” literally straying from the furrow; it can mean confused mental disturbance or extreme excitement.','delirium'),contexts:[C('delirium.s1','临床观察','The nurse reported sudden delirium when the patient became confused about the date and could not follow a familiar conversation.','患者突然混乱，记不清日期，也无法跟上熟悉的谈话，护士因此报告了谵妄情况。','The nurse reported sudden delirium / when the patient became confused about the date / and could not follow a familiar conversation.','delirium 为医学名词；语境描述意识混乱，而非普通失望。','突然意识混乱、无法理解对话，符合 s1。'),C('delirium.s2','体育庆典','The final goal sent the home crowd into delirium, with supporters cheering wildly long after the match ended.','最后一球让主场观众陷入狂热，比赛结束很久后球迷仍在疯狂欢呼。','The final goal sent the home crowd into delirium / with supporters cheering wildly / long after the match ended.','send sb into delirium 用比喻义描述难以控制的兴奋。','球迷持续狂喜庆祝，符合 s2。')],mistakes:[M('The patient was diagnosed with delirium because she was fully alert, knew the date, and followed every conversation clearly.','The patient was alert and oriented because she knew the date and followed conversations clearly.','意识清楚且定向正常与谵妄状态相矛盾。')],quiz:[Q('delirium',1,1,'A confused mental state often associated with illness is?',['delirium','deliberation','delectation'],'delirium','Delirium is a disturbed and confused state of mind.'),Q('delirium',2,2,'A crowd in wild, uncontrollable excitement is in a state of?',['delirium','deletion','deference'],'delirium','The figurative sense describes extreme excitement.'),Q('delirium',3,1,'Sudden confusion about time and place may indicate?',['delirium','deification','deflation'],'delirium','The clinical sense involves confusion and disturbed awareness.'),Q('delirium',4,2,'The fans celebrated in a delirium after the last-minute victory. They were?',['wildly excited','quietly calculating','unable to hear any sound'],'wildly excited','The word can figuratively mean intense, uncontrolled excitement.') ]});
  D('delta',{etymology:E('delta came into English through Greek letter names from Phoenician; the river-mouth landform is called a delta because its branching shape often resembles the Greek capital letter Δ.','delta'),contexts:[C('delta.s1','地理课堂','The river deposited silt across a broad delta, dividing into several channels before it reached the sea.','河流在广阔的三角洲沉积淤泥，入海前分成了几条水道。','The river deposited silt across a broad delta / dividing into several channels / before it reached the sea.','delta 指河流入海前分流形成的低地；dividing 补充河道形态。','河口分流并沉积泥沙，符合三角洲义。'),C('delta.s2','数学符号','In the equation, the Greek letter delta represents the change in temperature between the two measurements.','在这个方程中，希腊字母德尔塔代表两次测量之间的温度变化。','In the equation / the Greek letter delta represents the change in temperature / between the two measurements.','delta 作希腊字母名，也常作为变化量符号。','句中明确以希腊字母表示变量，符合 s2。')],mistakes:[M('The geographer called the high mountain peak a delta because it stood above the river and had no branching channels.','The geographer called the river-mouth plain a delta because the river divided into channels there.','高山顶峰不具河口沉积低地和分流特征。')],quiz:[Q('delta',1,1,'Low land formed where a river divides before entering the sea is a?',['delta','defile','deformity'],'delta','A river delta forms near its mouth as channels divide and sediment builds up.'),Q('delta',2,2,'The Greek letter Δ is named?',['delta','theta','omega'],'delta','Delta is the fourth letter of the Greek alphabet.'),Q('delta',3,1,'Which landscape is a delta?',['a sediment-rich river mouth with branching channels','a narrow pass between cliffs','a high bare mountain summit'],'a sediment-rich river mouth with branching channels','The branching channels and deposited sediment characterize a delta.'),Q('delta',4,2,'In science, delta often represents?',['a change or difference','a person’s rank','a sound’s loudness'],'a change or difference','The Greek letter is commonly used as a symbol for change.') ]});
  D('demagnetize',{etymology:E('demagnetize is formed from de- plus magnetize; magnet comes from Greek magnētis lithos, “Magnesian stone,” an early naturally magnetic mineral.','demagnetize'),contexts:[C('demagnetize.s1','设备维护','The technician used a demagnetizing tool to remove the unwanted magnetic field from the precision instrument.','技术员使用退磁工具去除精密仪器上多余的磁场。','The technician used a demagnetizing tool / to remove the unwanted magnetic field / from the precision instrument.','demagnetize 是及物动词，remove the field 说明消磁结果。','工具去掉器件磁性，符合 s1。')],mistakes:[M('The workshop demagnetized the steel part by exposing it to a strong field until its magnetism became even stronger.','The workshop magnetized the steel part by exposing it to a strong field until its magnetism became stronger.','增强磁性是 magnetize；demagnetize 是去除或减弱磁性。','confusable')],quiz:[Q('demagnetize',1,1,'To demagnetize a tool is to?',['remove or reduce its magnetism','make its magnetism stronger','measure its temperature'],'remove or reduce its magnetism','The verb means to take magnetic force away.'),Q('demagnetize',2,1,'A technician demagnetizes a screwdriver to?',['stop it attracting metal filings','make it attract more metal filings','turn it into a plastic tool'],'stop it attracting metal filings','Removing its magnetic field prevents unwanted attraction.'),Q('demagnetize',3,1,'Which result shows that a device was demagnetized?',['its unwanted magnetic field is gone','its magnetic force has increased','its housing has changed colour'],'its unwanted magnetic field is gone','Demagnetizing removes magnetic force.'),Q('demagnetize',4,1,'The prefix de- in demagnetize indicates?',['removing or reversing magnetism','measuring one tenth of a magnet','making a magnet decorative'],'removing or reversing magnetism','Demagnetize means to undo or remove magnetization.') ]});
  D('demagogue',{etymology:E('demagogue comes from Greek dēmagōgos, “leader of the people,” from dēmos “people” and agōgos “leading”; modern English usually criticizes a leader who stirs emotion and prejudice for power.','demagogue'),contexts:[C('demagogue.s1','政治修辞','The demagogue blamed minority groups for complex economic problems and urged the crowd to reject evidence in favor of anger.','这位煽动者把复杂的经济问题归咎于少数群体，并煽动人群抛弃证据、听从愤怒。','The demagogue blamed minority groups for complex economic problems / and urged the crowd / to reject evidence in favor of anger.','demagogue 是带贬义的政治人物名词；后续动作体现其煽动手法。','利用偏见和情绪谋取支持，而不是理性论证，符合词义。')],mistakes:[M('The demagogue calmly presented verifiable evidence, welcomed criticism, and persuaded voters through careful reasoning alone.','The civic educator calmly presented verifiable evidence, welcomed criticism, and persuaded voters through careful reasoning.','理性陈证、欢迎质疑不体现靠煽动激情和偏见争取权力。')],quiz:[Q('demagogue',1,1,'A politician who gains support by stirring prejudice and emotion is a?',['demagogue','decomposer','decorator'],'demagogue','A demagogue appeals to passion and prejudice rather than reason.'),Q('demagogue',2,1,'Which behavior best fits demagogue?',['blaming a vulnerable group to inflame a crowd','weighing evidence and acknowledging uncertainty','explaining a budget in neutral terms'],'blaming a vulnerable group to inflame a crowd','Scapegoating and emotional agitation are demagogic tactics.'),Q('demagogue',3,1,'The modern word demagogue is generally?',['critical or disapproving','a neutral term for any public speaker','a unit of measurement'],'critical or disapproving','The term carries a strongly negative political judgment.'),Q('demagogue',4,1,'A demagogue seeks political power chiefly by?',['stirring passions and prejudice','careful reasoned debate alone','refusing to address an audience'],'stirring passions and prejudice','Emotional appeals rather than reason are central to the word.') ]});
})(globalThis);
